export const BOARD_PAGE = "<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>Listing Lab dashboard</title>\n<meta name=\"robots\" content=\"noindex, nofollow\">\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n<link href=\"https://fonts.googleapis.com/css2?family=Fraunces:opsz,wght@9..144,400;9..144,500;9..144,600;9..144,700&family=Inter:wght@400;500;600;700&display=swap\" rel=\"stylesheet\">\n</head><body>\n\n\n\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n<link href=\"https://fonts.googleapis.com/css2?family=Fraunces:opsz,wght@9..144,400;9..144,500;9..144,600;9..144,700&family=Inter:wght@400;500;600;700&display=swap\" rel=\"stylesheet\">\n\n<style>\n/* ============================================================\n   LISTING LAB — design tokens\n   Two deliberate registers, not OS-theme driven:\n   - \"Studio Light\": marketing / editorial surfaces (warm paper)\n   - \"Studio Dark\": the working canvas (AI Studio, dashboard, etc.)\n   Photo tools conventionally run a fixed dark workspace so imagery\n   reads correctly regardless of the visitor's OS theme; the\n   marketing site stays a warm paper register at all times so the\n   brand reads consistently. Both are explicit, not inherited.\n   ============================================================ */\n:root{\n  /* Horizon Home Media brand: azure blue (from the logo, ~#3E79B9),\n     black, white. Dark register site-wide — a blue-black canvas so the\n     light illustrations read as the photography, with the brand blue\n     as the single accent and a light azure in the secondary role.\n     (--pine/--brass keep their names as ROLE tokens: accent/secondary.) */\n  --paper: #0F141B;\n  --paper-2: #151C25;\n  --paper-3: #1B2431;\n  --ink: #E9EDF3;\n  --ink-soft: #A6B1BF;\n  --ink-faint: #75818F;\n  --pine: #4E8FD0;\n  --pine-deep: #14304F;\n  --pine-bright: #66A2DE;\n  --brass: #8FBEE8;\n  --brass-soft: #C9DFF2;\n  --terracotta: #E17A5C;\n  --line: #2A3545;\n  --mist: #E7EBDF;\n  --shadow: 215 25% 10%;\n\n  --studio-bg: #0C1118;\n  --studio-surface: #131A24;\n  --studio-surface-2: #19222E;\n  --studio-surface-3: #1F2938;\n  --studio-line: #293546;\n  --studio-text: #E9EDF3;\n  --studio-text-soft: #A0ABBA;\n  --studio-text-faint: #6B7787;\n  --studio-pine: #4E8FD0;\n  --studio-brass: #8FBEE8;\n  --studio-terracotta: #E17A5C;\n\n  --r-sm: 6px;\n  --r-md: 10px;\n  --r-lg: 18px;\n  --r-xl: 28px;\n\n  --display: \"Fraunces\", \"Iowan Old Style\", Georgia, serif;\n  --ui: \"Inter\", -apple-system, BlinkMacSystemFont, \"Segoe UI\", sans-serif;\n}\n\n*,*::before,*::after{box-sizing:border-box;}\nhtml,body{margin:0;padding:0;}\nbody{\n  background:var(--paper);\n  color:var(--ink);\n  font-family:var(--ui);\n  -webkit-font-smoothing:antialiased;\n  text-rendering:optimizeLegibility;\n  overflow-x:hidden;\n}\nimg,svg{max-width:100%;display:block;}\n/* Default size for standalone inline icon SVGs (unsized ones otherwise\n   render at the browser's intrinsic replaced-element size). Components\n   with their own icon size (.mark svg, .ba-knob svg, etc.) override this\n   via higher-specificity selectors below. */\nsvg{width:18px;height:18px;flex-shrink:0;}\n.pill svg{width:12px;height:12px;}\na{color:inherit;text-decoration:none;}\nbutton{font-family:inherit;cursor:pointer;}\nh1,h2,h3,h4{font-family:var(--display);font-weight:600;margin:0;text-wrap:balance;letter-spacing:-0.01em;}\np{margin:0;}\n::selection{background:var(--brass-soft);color:var(--pine-deep);}\n:focus-visible{outline:2px solid var(--pine);outline-offset:2px;}\n.studio :focus-visible{outline:2px solid var(--studio-pine);}\n@media (prefers-reduced-motion: reduce){\n  *{animation-duration:0.001ms !important;transition-duration:0.001ms !important;}\n}\n\n.eyebrow{\n  font-size:0.72rem;letter-spacing:0.14em;text-transform:uppercase;\n  font-weight:600;color:var(--pine);\n}\n.studio .eyebrow{color:var(--studio-brass);}\n\n/* ---------- layout helpers ---------- */\n.wrap{max-width:1180px;margin:0 auto;padding:0 32px;}\n@media(max-width:720px){.wrap{padding:0 20px;}}\n.btn{\n  display:inline-flex;align-items:center;justify-content:center;gap:8px;\n  padding:13px 24px;border-radius:999px;border:1px solid transparent;\n  font-size:0.92rem;font-weight:600;letter-spacing:0.01em;\n  transition:transform .18s ease, box-shadow .18s ease, background .18s ease, border-color .18s ease;\n  white-space:nowrap;\n}\n.btn:active{transform:scale(0.97);}\n.btn-primary{background:var(--pine);color:#0A1017;box-shadow:0 8px 22px -10px rgba(78,143,208,.45);}\n.btn-primary:hover{background:var(--pine-bright);box-shadow:0 10px 26px -10px rgba(78,143,208,.5);}\n.btn-ghost{background:transparent;color:var(--ink);border-color:var(--line);}\n.btn-ghost:hover{border-color:var(--ink-faint);background:var(--paper-2);}\n.btn-quiet{background:transparent;color:var(--ink-soft);padding:10px 6px;}\n.btn-quiet:hover{color:var(--ink);}\n.btn-sm{padding:9px 16px;font-size:0.82rem;}\n.btn-block{width:100%;}\n.btn[disabled]{opacity:.45;cursor:not-allowed;transform:none !important;}\n\n.studio .btn-primary{background:var(--studio-pine);color:#0A1017;box-shadow:0 8px 22px -10px rgba(78,143,208,.45);}\n.studio .btn-primary:hover{background:var(--pine-bright);}\n.studio .btn-ghost{color:var(--studio-text);border-color:var(--studio-line);}\n.studio .btn-ghost:hover{border-color:#3d4f45;background:var(--studio-surface-2);}\n.studio .btn-quiet{color:var(--studio-text-soft);}\n.studio .btn-quiet:hover{color:var(--studio-text);}\n\n.pill{\n  display:inline-flex;align-items:center;gap:6px;\n  padding:5px 12px;border-radius:999px;font-size:0.72rem;font-weight:600;\n  letter-spacing:0.04em;text-transform:uppercase;\n}\n.pill-approved{background:#E1EEE5;color:var(--pine-deep);}\n.pill-rejected{background:#F3DED7;color:var(--terracotta);}\n.pill-processing{background:var(--paper-3);color:var(--ink-soft);}\n.studio .pill-approved{background:rgba(78,143,208,.16);color:var(--studio-pine);}\n.studio .pill-rejected{background:rgba(225,122,92,.16);color:var(--studio-terracotta);}\n.studio .pill-processing{background:var(--studio-surface-3);color:var(--studio-text-soft);}\n\n.card{\n  background:var(--paper-2);border:1px solid var(--line);border-radius:var(--r-lg);\n  transition:transform .25s ease, box-shadow .25s ease, border-color .25s ease;\n}\n.studio .card{background:var(--studio-surface);border-color:var(--studio-line);}\n\nhr.rule{border:none;border-top:1px solid var(--line);margin:0;}\n.studio hr.rule{border-top:1px solid var(--studio-line);}\n\n/* ---------- mark / logo ----------\n   Lockup echoes the Horizon Home Media logo: heavy dark caps for the\n   lead word, lighter letterspaced blue caps for the second — the same\n   HORIZON / HOME MEDIA relationship, one register down. */\n.mark{display:inline-flex;align-items:center;gap:11px;font-family:var(--ui);font-weight:800;font-size:0.98rem;letter-spacing:0.11em;text-transform:uppercase;}\n.mark svg{width:27px;height:27px;flex:none;}\n.mark .lab{color:var(--pine);font-weight:600;letter-spacing:0.16em;margin-left:1px;}\n.studio .mark .lab{color:var(--studio-pine);}\n.wordmark-lab{color:var(--brass);}\n.studio .wordmark-lab{color:var(--studio-brass);}\n\n/* ============================================================\n   MARKETING SITE\n   ============================================================ */\n.site{background:var(--paper);}\n.site-nav{\n  position:sticky;top:0;z-index:40;background:rgba(15,20,27,.88);backdrop-filter:blur(10px);\n  border-bottom:1px solid var(--line);\n}\n.site-nav-row{display:flex;align-items:center;justify-content:space-between;height:76px;}\n.site-nav-links{display:flex;align-items:center;gap:34px;font-size:0.9rem;font-weight:500;color:var(--ink-soft);}\n.site-nav-links a:hover{color:var(--ink);}\n.site-nav-cta{display:flex;align-items:center;gap:18px;}\n.nav-toggle{display:none;}\n@media(max-width:860px){\n  .site-nav-links{display:none;}\n}\n\n.hero{padding:76px 0 40px;position:relative;overflow:hidden;}\n.hero-grid{display:grid;grid-template-columns:1.02fr 1fr;gap:56px;align-items:center;}\n@media(max-width:980px){.hero-grid{grid-template-columns:1fr;gap:40px;}}\n.hero-eyebrow{margin-bottom:22px;}\n.hero h1{font-size:clamp(2.5rem,5vw,3.7rem);line-height:1.05;color:var(--ink);}\n.hero-sub{margin-top:22px;font-size:1.13rem;line-height:1.6;color:var(--ink-soft);max-width:46ch;}\n.hero-cta{display:flex;gap:14px;margin-top:34px;flex-wrap:wrap;}\n.hero-proof{display:flex;gap:28px;margin-top:44px;flex-wrap:wrap;}\n.hero-proof-item{font-size:0.82rem;color:var(--ink-faint);max-width:170px;line-height:1.45;}\n.hero-proof-item b{display:block;font-family:var(--display);font-size:1.5rem;color:var(--pine);font-weight:600;}\n\n/* before/after aperture reveal */\n.ba{\n  position:relative;border-radius:var(--r-xl);overflow:hidden;aspect-ratio:4/3;\n  box-shadow:0 30px 60px -30px rgba(0,0,0,.6);border:1px solid var(--line);\n  user-select:none;background:var(--paper-2);\n}\n.ba .ba-layer{position:absolute;inset:0;}\n.ba .ba-after{clip-path:inset(0 0 0 var(--ba-pos,50%));}\n.ba-handle{\n  position:absolute;top:0;bottom:0;left:var(--ba-pos,50%);width:0;\n  transform:translateX(-50%);cursor:ew-resize;touch-action:none;\n}\n.ba-handle::before{content:\"\";position:absolute;top:0;bottom:0;left:50%;width:2px;background:#F7FAFD;transform:translateX(-50%);box-shadow:0 0 0 1px rgba(0,0,0,.08);}\n.ba-knob{\n  position:absolute;top:50%;left:50%;transform:translate(-50%,-50%);\n  width:52px;height:52px;border-radius:50%;background:#F7FAFD;color:#141B24;\n  display:flex;align-items:center;justify-content:center;gap:5px;\n  box-shadow:0 8px 18px -6px rgba(0,0,0,.35);\n}\n.ba-knob svg{width:14px;height:14px;}\n.ba-tag{\n  position:absolute;top:16px;padding:6px 13px;border-radius:999px;font-size:0.72rem;\n  font-weight:700;letter-spacing:0.08em;text-transform:uppercase;background:rgba(22,33,27,.72);\n  color:#F2F5F9;backdrop-filter:blur(4px);\n}\n.ba-tag.tag-before{left:16px;}\n.ba-tag.tag-after{right:16px;background:rgba(30,74,58,.82);}\n\n.marquee{\n  padding:26px 0;border-top:1px solid var(--line);border-bottom:1px solid var(--line);\n  display:flex;gap:48px;overflow:hidden;white-space:nowrap;\n}\n.marquee span{font-family:var(--display);font-size:1.02rem;color:var(--ink-faint);flex:none;}\n\n.section{padding:104px 0;}\n.section-head{max-width:640px;margin:0 auto 56px;text-align:center;}\n.section-head h2{font-size:clamp(1.9rem,3.4vw,2.6rem);margin-top:16px;}\n.section-head p{margin-top:16px;color:var(--ink-soft);font-size:1.05rem;line-height:1.6;}\n\n/* compliance flow diagram */\n.flow{display:flex;align-items:stretch;justify-content:space-between;gap:0;margin-top:64px;}\n.flow-step{flex:1;text-align:center;padding:0 8px;position:relative;}\n.flow-step .flow-num{\n  width:52px;height:52px;border-radius:50%;margin:0 auto 18px;background:var(--pine);\n  color:#0A1017;display:flex;align-items:center;justify-content:center;font-family:var(--display);font-weight:600;font-size:1.15rem;\n}\n.flow-step h4{font-size:1rem;margin-bottom:8px;}\n.flow-step p{font-size:0.85rem;color:var(--ink-faint);line-height:1.5;}\n.flow-connector{flex:0 0 auto;width:60px;display:flex;align-items:center;justify-content:center;padding-top:26px;color:var(--brass);}\n@media(max-width:860px){\n  .flow{flex-direction:column;gap:28px;}\n  .flow-connector{width:auto;transform:rotate(90deg);padding:0;}\n}\n\n.compliance-band{\n  background:var(--pine-deep);color:#EEE9DA;border-radius:var(--r-xl);padding:64px 56px;\n  border:1px solid #1F4064;\n}\n.compliance-band .section-head p{color:#C2D2E4;}\n.compliance-band .section-head{color:#EEE9DA;}\n.compliance-band .section-head h2{color:#EEE9DA;}\n.compliance-band .flow-step .flow-num{background:var(--brass);color:var(--pine-deep);}\n.compliance-band .flow-step h4{color:#EEE9DA;}\n.compliance-band .flow-step p{color:#AFC2D6;}\n@media(max-width:720px){.compliance-band{padding:48px 26px;}}\n\n/* capability sections */\n.capability{display:grid;grid-template-columns:1fr 1fr;gap:64px;align-items:center;padding:88px 0;}\n.capability:nth-child(even){direction:rtl;}\n.capability:nth-child(even) > *{direction:ltr;}\n@media(max-width:940px){.capability{grid-template-columns:1fr;gap:36px;direction:ltr !important;padding:56px 0;}\n  .capability > *{direction:ltr !important;}}\n.capability-copy .cap-index{font-family:var(--display);font-size:0.95rem;color:var(--brass);font-weight:600;}\n.capability-copy h3{font-size:clamp(1.7rem,3vw,2.3rem);margin-top:14px;}\n.capability-copy p{margin-top:18px;color:var(--ink-soft);font-size:1.03rem;line-height:1.65;max-width:44ch;}\n.cap-points{margin-top:26px;display:flex;flex-direction:column;gap:12px;}\n.cap-point{display:flex;gap:10px;align-items:flex-start;font-size:0.92rem;color:var(--ink-soft);}\n.cap-point svg{width:18px;height:18px;flex:none;margin-top:2px;color:var(--pine);}\n.cap-credit{margin-top:28px;display:inline-flex;align-items:center;gap:10px;padding:10px 18px;border:1px solid var(--line);border-radius:999px;font-size:0.85rem;color:var(--ink-soft);}\n.cap-credit b{color:var(--ink);}\n\n/* pricing */\n.pricing-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:24px;margin-top:20px;}\n@media(max-width:860px){.pricing-grid{grid-template-columns:1fr;}}\n.price-card{padding:36px 30px;position:relative;}\n.price-card.featured{border-color:var(--pine);box-shadow:0 20px 40px -24px rgba(10,25,45,.4);}\n.price-card .featured-tag{position:absolute;top:-13px;left:30px;background:var(--pine);color:#0A1017;font-size:0.68rem;letter-spacing:0.08em;text-transform:uppercase;font-weight:700;padding:5px 12px;border-radius:999px;}\n.price-card h4{font-size:1.05rem;color:var(--ink-soft);font-weight:600;}\n.price-card .price-num{font-family:var(--display);font-size:2.6rem;margin:14px 0 4px;color:var(--ink);}\n.price-card .price-num small{font-size:1rem;font-weight:500;color:var(--ink-faint);}\n.price-card .price-credits{font-size:0.85rem;color:var(--ink-faint);margin-bottom:26px;}\n.price-list{list-style:none;padding:0;margin:0 0 28px;display:flex;flex-direction:column;gap:10px;font-size:0.86rem;color:var(--ink-soft);}\n.price-list li{display:flex;gap:8px;}\n.price-list svg{width:16px;height:16px;color:var(--pine);flex:none;margin-top:2px;}\n\n.site-footer{background:#0A0E14;color:#C4CDD8;padding:64px 0 32px;border-top:1px solid var(--line);}\n.footer-grid{display:grid;grid-template-columns:1.6fr 1fr 1fr 1fr;gap:40px;}\n@media(max-width:780px){.footer-grid{grid-template-columns:1fr 1fr;}}\n.footer-grid h5{color:#7C8896;font-size:0.75rem;letter-spacing:0.08em;text-transform:uppercase;margin-bottom:16px;font-weight:600;}\n.footer-grid ul{list-style:none;padding:0;margin:0;display:flex;flex-direction:column;gap:10px;font-size:0.88rem;}\n.footer-grid ul a:hover{color:#fff;}\n.footer-bottom{margin-top:56px;padding-top:24px;border-top:1px solid #27303E;display:flex;justify-content:space-between;flex-wrap:wrap;gap:12px;font-size:0.8rem;color:#6B7684;}\n\n/* ============================================================\n   ROOM ILLUSTRATIONS  (original line-art, not photography)\n   ============================================================ */\n.room{position:relative;width:100%;height:100%;border-radius:inherit;overflow:hidden;background:var(--paper-2);}\n.room svg{width:100%;height:100%;display:block;}\n.room .clutter,.room .staged{transition:opacity .3s ease;}\n.room.state-before .staged{display:none;}\n.room.state-after .clutter{display:none;}\n.room.state-empty .staged,.room.state-empty .clutter{display:none;}\n\n.room.style-modern{--a:#33383F;--b:#CDC5B2;--c:#8B8F86;}\n.room.style-transitional{--a:#5B4636;--b:#E7DEC7;--c:#A98B5E;}\n.room.style-contemporary{--a:#191919;--b:#F2EFE7;--c:#AD463C;}\n.room.style-coastal{--a:#E9E3D2;--b:#3E6E78;--c:#F4F1E8;}\n.room.style-luxury{--a:#1E4A3A;--b:#B98A46;--c:#20241f;}\n\n.room.time-day{--sky1:#CFE6EA;--sky2:#DCE7D0;--sky3:#E7DEC0;}\n.room.time-golden{--sky1:#FBCE84;--sky2:#EE8F63;--sky3:#7C4E63;--glow:#FFD37E;}\n.room.time-dusk{--sky1:#8D6E90;--sky2:#4C5B85;--sky3:#1F2645;--glow:#FFB877;}\n.room.time-blue{--sky1:#42527D;--sky2:#212D54;--sky3:#0C1330;--glow:#FFD6A0;}\n\n/* ============================================================\n   APP SHELL (dark canvas)\n   ============================================================ */\n.studio{background:var(--studio-bg);color:var(--studio-text);min-height:100vh;}\n.studio-topbar{\n  position:sticky;top:0;z-index:30;background:rgba(12,17,24,.9);backdrop-filter:blur(10px);\n  border-bottom:1px solid var(--studio-line);\n}\n.studio-topbar-row{display:flex;align-items:center;justify-content:space-between;height:68px;}\n.studio-nav{display:flex;align-items:center;gap:6px;}\n.studio-nav a{\n  padding:9px 15px;border-radius:999px;font-size:0.87rem;font-weight:500;color:var(--studio-text-soft);\n  display:flex;align-items:center;gap:7px;transition:background .15s ease,color .15s ease;\n}\n.studio-nav a:hover{color:var(--studio-text);background:var(--studio-surface-2);}\n.studio-nav a.active{background:var(--studio-surface-2);color:var(--studio-text);}\n.studio-nav svg{width:16px;height:16px;}\n@media(max-width:900px){.studio-nav span.nav-label{display:none;}}\n\n.credit-chip{\n  display:flex;align-items:center;gap:8px;padding:8px 14px;border-radius:999px;\n  background:var(--studio-surface-2);border:1px solid var(--studio-line);font-size:0.85rem;font-weight:600;\n}\n.credit-chip svg{width:15px;height:15px;color:var(--studio-brass);}\n\n.crumbs{display:flex;align-items:center;gap:8px;font-size:0.83rem;color:var(--studio-text-faint);padding:20px 0 0;flex-wrap:wrap;}\n.crumbs a{color:var(--studio-text-soft);}\n.crumbs a:hover{color:var(--studio-text);}\n.crumbs .sep{opacity:.5;}\n.crumbs .current{color:var(--studio-text);font-weight:600;}\n\n.page-head{display:flex;align-items:flex-end;justify-content:space-between;gap:20px;padding:18px 0 32px;flex-wrap:wrap;}\n.page-head h1{font-size:2rem;color:var(--studio-text);}\n.page-head p{color:var(--studio-text-soft);margin-top:8px;font-size:0.95rem;}\n\n.grid-3{display:grid;grid-template-columns:repeat(3,1fr);gap:22px;}\n.grid-4{display:grid;grid-template-columns:repeat(4,1fr);gap:20px;}\n@media(max-width:960px){.grid-3{grid-template-columns:repeat(2,1fr);}.grid-4{grid-template-columns:repeat(2,1fr);}}\n@media(max-width:600px){.grid-3,.grid-4{grid-template-columns:1fr;}}\n\n/* dashboard stat cards */\n.stat-row{display:grid;grid-template-columns:1.1fr 1fr 1fr;gap:20px;margin-bottom:40px;}\n@media(max-width:820px){.stat-row{grid-template-columns:1fr;}}\n.stat-card{padding:26px 28px;}\n.stat-card .stat-label{font-size:0.78rem;color:var(--studio-text-faint);text-transform:uppercase;letter-spacing:0.06em;font-weight:600;}\n.stat-card .stat-value{font-family:var(--display);font-size:2.3rem;margin-top:10px;color:var(--studio-text);font-variant-numeric:tabular-nums;}\n.stat-card .stat-sub{font-size:0.85rem;color:var(--studio-text-soft);margin-top:8px;}\n\n/* listing card */\n.listing-card{overflow:hidden;cursor:pointer;}\n.listing-card:hover{transform:translateY(-3px);border-color:#3d4f45;}\n.listing-thumb{aspect-ratio:4/3;position:relative;}\n.listing-info{padding:20px 22px 22px;}\n.listing-info .addr{font-family:var(--display);font-size:1.15rem;color:var(--studio-text);}\n.listing-info .city{font-size:0.85rem;color:var(--studio-text-soft);margin-top:4px;}\n.listing-meta{display:flex;gap:16px;margin-top:16px;font-size:0.78rem;color:var(--studio-text-faint);}\n.listing-meta span{display:flex;align-items:center;gap:5px;}\n.listing-meta svg{width:13px;height:13px;}\n\n.recent-row{display:flex;align-items:center;gap:16px;padding:16px 0;}\n.recent-row + .recent-row{border-top:1px solid var(--studio-line);}\n.recent-thumb{width:56px;height:56px;border-radius:var(--r-md);overflow:hidden;flex:none;}\n.recent-body{flex:1;min-width:0;}\n.recent-body .r-title{font-size:0.92rem;font-weight:600;color:var(--studio-text);}\n.recent-body .r-sub{font-size:0.8rem;color:var(--studio-text-soft);margin-top:3px;}\n\n/* photo gallery */\n.photo-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:16px;}\n@media(max-width:960px){.photo-grid{grid-template-columns:repeat(3,1fr);}}\n@media(max-width:640px){.photo-grid{grid-template-columns:repeat(2,1fr);}}\n.photo-tile{position:relative;aspect-ratio:4/3;border-radius:var(--r-md);overflow:hidden;cursor:pointer;border:1px solid var(--studio-line);transition:transform .2s ease;}\n.photo-tile:hover{transform:scale(1.02);}\n.photo-tile .tile-badge{position:absolute;top:8px;left:8px;background:rgba(12,17,24,.78);color:var(--studio-brass);font-size:0.62rem;font-weight:700;letter-spacing:0.06em;text-transform:uppercase;padding:4px 8px;border-radius:999px;}\n.photo-tile .tile-room{position:absolute;bottom:8px;left:8px;color:#fff;font-size:0.72rem;font-weight:600;text-shadow:0 1px 4px rgba(0,0,0,.5);}\n\n/* photo viewer */\n/* minmax(0,1fr): a plain 1fr track's min-size is content-based, and the\n   stage's aspect-ratio transfers the (taller) side panel's row height into\n   a min-content WIDTH, inflating the track until the panel overflows the\n   page. Clamping the min to 0 keeps the stage at the free space. */\n.viewer-shell{display:grid;grid-template-columns:minmax(0,1fr) 300px;gap:0;border-radius:var(--r-lg);overflow:hidden;border:1px solid var(--studio-line);}\n@media(max-width:900px){.viewer-shell{grid-template-columns:1fr;}}\n.viewer-stage{position:relative;background:#090D13;aspect-ratio:4/3;}\n.viewer-side{background:var(--studio-surface);padding:26px;display:flex;flex-direction:column;gap:22px;}\n.viewer-toggle{display:inline-flex;background:var(--studio-surface-3);border-radius:999px;padding:4px;gap:4px;align-self:flex-start;}\n.viewer-toggle button{padding:8px 16px;border-radius:999px;border:none;background:transparent;color:var(--studio-text-soft);font-size:0.82rem;font-weight:600;}\n.viewer-toggle button.active{background:var(--studio-pine);color:#0A1017;}\n.filmstrip{display:flex;gap:10px;overflow-x:auto;padding:16px 0 4px;}\n.filmstrip img,.filmstrip .fs-item{width:64px;height:48px;border-radius:6px;flex:none;border:2px solid transparent;cursor:pointer;overflow:hidden;}\n.filmstrip .fs-item.active{border-color:var(--studio-pine);}\n\n/* AI studio */\n.studio-shell{display:grid;grid-template-columns:minmax(0,1fr) 340px;gap:0;border-radius:var(--r-lg);overflow:hidden;border:1px solid var(--studio-line);}\n@media(max-width:940px){.studio-shell{grid-template-columns:1fr;}}\n.studio-stage{background:#090D13;position:relative;aspect-ratio:4/3;display:flex;align-items:center;justify-content:center;}\n.studio-stage .ba{width:100%;height:100%;border-radius:0;border:none;box-shadow:none;}\n.studio-panel{background:var(--studio-surface);display:flex;flex-direction:column;}\n.tf-tabs{display:flex;border-bottom:1px solid var(--studio-line);}\n.tf-tab{flex:1;padding:16px 8px;text-align:center;font-size:0.82rem;font-weight:600;color:var(--studio-text-faint);border-bottom:2px solid transparent;}\n.tf-tab.active{color:var(--studio-text);border-color:var(--studio-pine);}\n.tf-body{padding:24px;display:flex;flex-direction:column;gap:22px;flex:1;}\n.tf-desc{font-size:0.86rem;color:var(--studio-text-soft);line-height:1.55;}\n.opt-label{font-size:0.75rem;text-transform:uppercase;letter-spacing:0.07em;color:var(--studio-text-faint);font-weight:700;margin-bottom:10px;}\n.opt-grid{display:grid;grid-template-columns:1fr 1fr;gap:9px;}\n.opt-chip{\n  padding:11px 12px;border-radius:var(--r-md);border:1px solid var(--studio-line);background:var(--studio-surface-2);\n  font-size:0.83rem;font-weight:600;color:var(--studio-text-soft);text-align:left;transition:all .15s ease;\n}\n.opt-chip:hover{border-color:#456;}\n.opt-chip.selected{border-color:var(--studio-pine);background:rgba(78,143,208,.14);color:var(--studio-text);}\n.opt-chip .swatch{display:inline-block;width:9px;height:9px;border-radius:50%;margin-right:7px;}\n.tf-footer{margin-top:auto;padding:20px 24px;border-top:1px solid var(--studio-line);display:flex;flex-direction:column;gap:14px;}\n.cost-row{display:flex;align-items:center;justify-content:space-between;font-size:0.88rem;color:var(--studio-text-soft);}\n.cost-row b{color:var(--studio-text);font-size:1rem;}\n.demo-toggle{\n  display:flex;align-items:center;gap:8px;font-size:0.72rem;color:var(--studio-text-faint);\n  border:1px dashed var(--studio-line);border-radius:var(--r-sm);padding:8px 10px;\n}\n.demo-toggle input{accent-color:var(--studio-terracotta);}\n\n/* watermark badge on generated images */\n.wm-badge{\n  position:absolute;left:50%;bottom:18px;transform:translateX(-50%);\n  background:rgba(9,13,19,.85);color:#F2F5F9;border:1px solid rgba(255,255,255,.16);\n  padding:8px 16px;border-radius:6px;font-size:0.72rem;font-weight:700;letter-spacing:0.08em;\n  text-transform:uppercase;white-space:nowrap;box-shadow:0 6px 18px rgba(0,0,0,.35);\n}\n\n/* generation overlay */\n.overlay{position:fixed;inset:0;background:rgba(7,10,15,.72);backdrop-filter:blur(4px);z-index:100;display:flex;align-items:center;justify-content:center;padding:20px;}\n.overlay-card{width:100%;max-width:440px;background:var(--studio-surface);border:1px solid var(--studio-line);border-radius:var(--r-xl);padding:40px 36px;}\n.gen-steps{display:flex;flex-direction:column;gap:0;margin-top:28px;}\n.gen-step{display:flex;align-items:center;gap:14px;padding:11px 0;font-size:0.9rem;color:var(--studio-text-faint);}\n.gen-step .gs-icon{width:22px;height:22px;border-radius:50%;flex:none;display:flex;align-items:center;justify-content:center;border:1.5px solid var(--studio-line);}\n.gen-step.done{color:var(--studio-text);}\n.gen-step.done .gs-icon{background:var(--studio-pine);border-color:var(--studio-pine);}\n.gen-step.done .gs-icon svg{width:12px;height:12px;color:#0A1017;}\n.gen-step.active{color:var(--studio-text);}\n.gen-step.active .gs-icon{border-color:var(--studio-pine);}\n.gen-step.failed .gs-icon{background:var(--studio-terracotta);border-color:var(--studio-terracotta);}\n.gen-step.failed{color:var(--studio-terracotta);}\n.spin{width:10px;height:10px;border-radius:50%;border:2px solid var(--studio-line);border-top-color:var(--studio-pine);animation:spin .7s linear infinite;}\n@keyframes spin{to{transform:rotate(360deg);}}\n\n.result-fail{text-align:center;padding:20px 6px 6px;}\n.result-fail .fail-icon{width:56px;height:56px;border-radius:50%;background:rgba(225,122,92,.14);display:flex;align-items:center;justify-content:center;margin:0 auto 22px;}\n.result-fail .fail-icon svg{width:26px;height:26px;color:var(--studio-terracotta);}\n\n/* result screen */\n.result-shell{display:grid;grid-template-columns:minmax(0,1fr) 320px;gap:24px;}\n@media(max-width:940px){.result-shell{grid-template-columns:1fr;}}\n.result-stage{position:relative;border-radius:var(--r-lg);overflow:hidden;border:1px solid var(--studio-line);aspect-ratio:4/3;background:#090D13;}\n.result-actions{display:flex;flex-direction:column;gap:12px;}\n\n/* credits */\n.pack-card{padding:30px 26px;position:relative;}\n.pack-card.best{border-color:var(--studio-pine);}\n.pack-card .best-tag{position:absolute;top:-12px;left:26px;background:var(--studio-pine);color:#0A1017;font-size:0.65rem;font-weight:700;letter-spacing:0.06em;text-transform:uppercase;padding:5px 11px;border-radius:999px;}\n\n/* history table */\n.hist-table{width:100%;border-collapse:collapse;font-size:0.87rem;}\n.hist-table th{text-align:left;font-size:0.72rem;text-transform:uppercase;letter-spacing:0.06em;color:var(--studio-text-faint);font-weight:700;padding:0 14px 12px;border-bottom:1px solid var(--studio-line);}\n.hist-table td{padding:14px;border-bottom:1px solid var(--studio-line);color:var(--studio-text-soft);vertical-align:middle;}\n.hist-table tr:last-child td{border-bottom:none;}\n.hist-thumb{width:52px;height:40px;border-radius:6px;overflow:hidden;}\n.hist-table .h-type{color:var(--studio-text);font-weight:600;}\n.filter-row{display:flex;gap:8px;margin-bottom:22px;}\n.filter-chip{padding:8px 16px;border-radius:999px;border:1px solid var(--studio-line);font-size:0.82rem;font-weight:600;color:var(--studio-text-soft);background:var(--studio-surface);}\n.filter-chip.active{background:var(--studio-pine);color:#0A1017;border-color:var(--studio-pine);}\n\n/* ============================================================\n   ADMIN DASHBOARD (Horizon-internal — not customer-facing)\n   Chart tokens: series colors validated for CVD + contrast on the\n   dark surface (validate_palette.js, all checks pass). Series hue\n   follows the transformation entity across every chart.\n   ============================================================ */\n.admin-badge{display:inline-flex;align-items:center;gap:6px;background:rgba(224,99,47,.15);color:#E0632F;font-size:0.66rem;font-weight:800;letter-spacing:0.1em;text-transform:uppercase;padding:5px 11px;border-radius:999px;}\n.viz{\n  --s1:#4E8FD0; /* Declutter */\n  --s2:#1BAF7A; /* Virtual Staging */\n  --s3:#E0632F; /* Twilight */\n  --viz-grid:#212C3A;\n  --viz-axis:#31405280;\n  --status-good:#0CA30C;\n  --status-crit:#D03B3B;\n}\n.kpi-row{display:grid;grid-template-columns:repeat(5,1fr);gap:16px;margin-bottom:26px;}\n@media(max-width:1080px){.kpi-row{grid-template-columns:repeat(3,1fr);}}\n@media(max-width:680px){.kpi-row{grid-template-columns:1fr 1fr;}}\n.kpi{padding:20px 22px;}\n.kpi .k-label{font-size:0.74rem;color:var(--studio-text-faint);font-weight:600;}\n.kpi .k-value{font-size:1.72rem;font-weight:650;color:var(--studio-text);margin-top:8px;font-family:var(--ui);}\n.kpi .k-delta{font-size:0.76rem;margin-top:6px;font-weight:600;}\n.kpi .k-delta.up{color:#3FBF3F;}\n.kpi .k-delta.muted{color:var(--studio-text-faint);font-weight:500;}\n.kpi svg.spark{width:100%;height:30px;margin-top:10px;}\n.admin-grid{display:grid;grid-template-columns:1.65fr 1fr;gap:22px;margin-bottom:26px;}\n@media(max-width:960px){.admin-grid{grid-template-columns:1fr;}}\n.chart-card{padding:24px 26px;}\n.chart-card h3{font-size:1.05rem;color:var(--studio-text);font-family:var(--ui);font-weight:650;}\n.chart-card .c-sub{font-size:0.8rem;color:var(--studio-text-faint);margin-top:4px;}\n.legend-row{display:flex;gap:18px;margin-top:14px;flex-wrap:wrap;}\n.legend-item{display:flex;align-items:center;gap:7px;font-size:0.78rem;color:var(--studio-text-soft);font-weight:600;}\n.legend-item .dot{width:10px;height:10px;border-radius:50%;}\n.chart-svg{width:100%;height:auto;display:block;margin-top:12px;}\n.chart-svg text{font-family:var(--ui);}\n.share-row{display:grid;grid-template-columns:110px 1fr 44px;align-items:center;gap:12px;margin-top:16px;}\n.share-row .s-label{font-size:0.82rem;color:var(--studio-text-soft);font-weight:600;}\n.share-row .s-val{font-size:0.85rem;color:var(--studio-text);font-weight:650;text-align:right;font-variant-numeric:tabular-nums;}\n.share-track{height:14px;position:relative;}\n.share-track .fill{height:100%;border-radius:0 4px 4px 0;}\n.meter{height:12px;border-radius:6px;background:#14351B;overflow:hidden;margin-top:12px;}\n.meter .fill{height:100%;background:var(--status-good);border-radius:6px;}\n.pill-pass{background:rgba(12,163,12,.14);color:#3FBF3F;}\n.pill-fail{background:rgba(208,59,59,.16);color:#E06565;}\n.admin-table-note{font-size:0.75rem;color:var(--studio-text-faint);margin-top:10px;}\n#chart-tip{\n  position:fixed;z-index:300;pointer-events:none;background:#0A0E14;border:1px solid var(--studio-line);\n  border-radius:10px;padding:10px 13px;font-size:0.78rem;color:var(--studio-text-soft);display:none;\n  box-shadow:0 10px 26px -8px rgba(0,0,0,.55);min-width:150px;\n}\n#chart-tip .t-title{color:var(--studio-text);font-weight:700;margin-bottom:6px;}\n#chart-tip .t-row{display:flex;align-items:center;justify-content:space-between;gap:14px;padding:2px 0;}\n#chart-tip .t-row .dot{width:8px;height:8px;border-radius:50%;display:inline-block;margin-right:6px;}\n#chart-tip .t-val{color:var(--studio-text);font-weight:650;font-variant-numeric:tabular-nums;}\n\n.admin-grid > *, .admin-grid-2 > *{min-width:0;}\n.chart-card{min-width:0;}\n.admin-grid-2{grid-template-columns:1fr 1fr;}\n@media(max-width:960px){.admin-grid-2{grid-template-columns:1fr;}}\n@media(max-width:700px){\n  .svc-row{flex-wrap:wrap;row-gap:8px;}\n  .svc-row .svc-desc{order:4;flex-basis:100%;}\n  .studio-topbar-row{flex-wrap:wrap;height:auto;padding:10px 0;gap:8px;justify-content:center;}\n  .admin-badge{font-size:0.6rem;}\n  .page-head h1{font-size:1.5rem;}\n  .kpi .k-value{font-size:1.4rem;}\n}\n\n/* owner kill switch */\n.svc-row{display:flex;align-items:center;gap:18px;padding:16px 0;}\n.svc-row + .svc-row{border-top:1px solid var(--studio-line);}\n.svc-row .svc-name{font-weight:700;color:var(--studio-text);font-size:0.95rem;min-width:130px;}\n.svc-row .svc-desc{flex:1;font-size:0.82rem;color:var(--studio-text-soft);line-height:1.5;}\n.svc-status{font-size:0.7rem;font-weight:800;letter-spacing:0.06em;text-transform:uppercase;padding:4px 10px;border-radius:999px;}\n.svc-status.on{background:rgba(12,163,12,.14);color:#3FBF3F;}\n.svc-status.off{background:rgba(208,59,59,.16);color:#E06565;}\n.switch{position:relative;width:48px;height:27px;flex:none;}\n.switch input{position:absolute;inset:0;width:100%;height:100%;opacity:0;margin:0;cursor:pointer;z-index:2;}\n.switch .track{position:absolute;inset:0;background:var(--studio-surface-3);border:1px solid var(--studio-line);border-radius:999px;transition:background .2s,border-color .2s;}\n.switch .knob{position:absolute;top:3.5px;left:4px;width:20px;height:20px;border-radius:50%;background:#8593A3;transition:transform .2s,background .2s;z-index:1;}\n.switch input:checked ~ .track{background:rgba(208,59,59,.28);border-color:#D03B3B;}\n.switch input:checked ~ .knob{transform:translateX(20px);background:#E06565;}\n\n.toast-stack{position:fixed;bottom:24px;left:50%;transform:translateX(-50%);z-index:200;display:flex;flex-direction:column;gap:10px;align-items:center;}\n.toast{background:#F7FAFD;color:#141B24;padding:13px 22px;border-radius:999px;font-size:0.87rem;font-weight:600;box-shadow:0 12px 30px -10px rgba(0,0,0,.5);display:flex;align-items:center;gap:9px;animation:toastIn .3s ease;}\n.toast svg{width:15px;height:15px;color:var(--studio-pine);}\n@keyframes toastIn{from{opacity:0;transform:translateY(10px);}to{opacity:1;transform:translateY(0);}}\n\n.empty-state{text-align:center;padding:70px 20px;color:var(--studio-text-soft);}\n.reveal{animation:fadeUp .5s ease both;}\n@keyframes fadeUp{from{opacity:0;transform:translateY(14px);}to{opacity:1;transform:translateY(0);}}\n</style>\n\n<div id=\"toast-root\" class=\"toast-stack\"></div>\n<div id=\"app\"></div>\n\n<script>\n(function(){\n\"use strict\";\n\n/* ============================================================\n   CONFIG — the closed set of everything the AI is allowed to do.\n   ============================================================ */\nconst TRANSFORMS = {\n  declutter: {\n    key:'declutter', label:'Declutter', cost:1,\n    tagline:'Remove movable clutter while preserving the property.',\n    watermark:'Digitally Altered — AI',\n  },\n  staging: {\n    key:'staging', label:'Virtual Staging', cost:2,\n    tagline:'Add tasteful, photorealistic furniture to an empty room.',\n    watermark:'Virtually Staged',\n    styles:['Modern','Transitional','Contemporary','Coastal','Luxury'],\n    rooms:['Living Room','Bedroom','Dining Room','Office','Other'],\n  },\n  twilight: {\n    key:'twilight', label:'Twilight', cost:1,\n    tagline:'Convert a daylight exterior into a realistic dusk scene.',\n    watermark:'Digitally Altered — AI',\n    styles:['Golden Hour','Dusk','Blue Hour'],\n  },\n};\nconst STYLE_CLASS = {Modern:'modern',Transitional:'transitional',Contemporary:'contemporary',Coastal:'coastal',Luxury:'luxury'};\nconst TIME_CLASS = {'Golden Hour':'golden','Dusk':'dusk','Blue Hour':'blue'};\n\nconst PACKS = [\n  {credits:10, price:19.99},\n  {credits:30, price:49.99, best:true},\n  {credits:75, price:99.99},\n];\n\n/* ============================================================\n   MOCK DATA\n   ============================================================ */\nfunction seedListings(){\n  return [\n    { id:'l1', addr:'123 Main Street', city:'West Hartford, CT', videos:2,\n      photos:[\n        {id:'p1', room:'Living Room', type:'living', beforeState:'before'},\n        {id:'p2', room:'Bedroom', type:'bedroom', beforeState:'empty'},\n        {id:'p3', room:'Exterior', type:'exterior', beforeState:'day'},\n        {id:'p4', room:'Dining Room', type:'dining', beforeState:'empty'},\n      ]},\n    { id:'l2', addr:'42 Oak Street', city:'Bristol, CT', videos:1,\n      photos:[\n        {id:'p5', room:'Living Room', type:'living', beforeState:'before'},\n        {id:'p6', room:'Office', type:'office', beforeState:'empty'},\n        {id:'p7', room:'Exterior', type:'exterior', beforeState:'day'},\n      ]},\n    { id:'l3', addr:'18 Harbor View Road', city:'Mystic, CT', videos:3,\n      photos:[\n        {id:'p8', room:'Exterior', type:'exterior', beforeState:'day'},\n        {id:'p9', room:'Living Room', type:'living', beforeState:'before'},\n        {id:'p10', room:'Bedroom', type:'bedroom', beforeState:'empty'},\n        {id:'p11', room:'Dining Room', type:'dining', beforeState:'empty'},\n      ]},\n  ];\n}\nfunction seedHistory(){\n  return [\n    {id:'h1', listingId:'l1', listingAddr:'123 Main Street', photoId:'p2', type:'staging', options:{style:'Luxury', room:'Bedroom'}, date:'Aug 18, 2026', status:'approved', cost:2},\n    {id:'h2', listingId:'l2', listingAddr:'42 Oak Street', photoId:'p5', type:'declutter', options:{}, date:'Aug 17, 2026', status:'approved', cost:1},\n    {id:'h3', listingId:'l3', listingAddr:'18 Harbor View Road', photoId:'p8', type:'twilight', options:{style:'Golden Hour'}, date:'Aug 15, 2026', status:'approved', cost:1},\n    {id:'h4', listingId:'l1', listingAddr:'123 Main Street', photoId:'p9', type:'staging', options:{style:'Coastal', room:'Living Room'}, date:'Aug 12, 2026', status:'rejected', cost:0},\n  ];\n}\nfunction seedResults(){\n  return {\n    r1: {id:'r1', listingId:'l1', photoId:'p2', type:'staging', options:{style:'Luxury', room:'Bedroom'}, status:'approved', createdAt:1},\n    r2: {id:'r2', listingId:'l2', photoId:'p5', type:'declutter', options:{}, status:'approved', createdAt:2},\n    r3: {id:'r3', listingId:'l3', photoId:'p8', type:'twilight', options:{style:'Golden Hour'}, status:'approved', createdAt:3},\n  };\n}\n\n/* ============================================================\n   STATE + PERSISTENCE\n   ============================================================ */\nconst DEFAULT_STATE = { credits:12, listings:seedListings(), history:seedHistory(), results:seedResults() };\nlet S = loadState();\n\nfunction loadState(){\n  try{\n    const raw = localStorage.getItem('listinglab_state_v1');\n    if(raw){\n      const parsed = JSON.parse(raw);\n      return Object.assign({}, DEFAULT_STATE, parsed, {listings: DEFAULT_STATE.listings});\n    }\n  }catch(e){}\n  return JSON.parse(JSON.stringify(DEFAULT_STATE));\n}\nfunction saveState(){\n  try{ localStorage.setItem('listinglab_state_v1', JSON.stringify({credits:S.credits, history:S.history, results:S.results})); }catch(e){}\n}\n\nfunction getListing(id){ return S.listings.find(l=>l.id===id); }\nfunction getPhoto(listingId, photoId){ const l=getListing(listingId); return l && l.photos.find(p=>p.id===photoId); }\n\nlet nextId = 100;\nfunction uid(prefix){ nextId++; return prefix+'_'+Date.now().toString(36)+nextId; }\n\n/* ============================================================\n   ICONS (inline, original — simple geometric line icons)\n   ============================================================ */\nconst ICON = {\n  /* Sub-brand mark: the two \"O\"s of the Horizon Home Media logo fused —\n     a six-blade aperture ring (the camera O) around a house with a lit\n     window (the home O). Ring in brand blue, house in currentColor. */\n  logoMark: (function(){\n    const r=10.3, cx=13, cy=13; let arcs='';\n    for(let i=0;i<6;i++){\n      const a0=(i*60-83)*Math.PI/180, a1=(i*60-37)*Math.PI/180;\n      arcs += `<path d=\"M${(cx+r*Math.cos(a0)).toFixed(2)} ${(cy+r*Math.sin(a0)).toFixed(2)} A${r} ${r} 0 0 1 ${(cx+r*Math.cos(a1)).toFixed(2)} ${(cy+r*Math.sin(a1)).toFixed(2)}\"/>`;\n    }\n    return `<svg viewBox=\"0 0 26 26\" fill=\"none\">`\n      + `<g stroke=\"var(--pine,#4E8FD0)\" stroke-width=\"3\" stroke-linecap=\"round\">${arcs}</g>`\n      + `<path d=\"M8.4 12.1L13 7.9L17.6 12.1\" stroke=\"currentColor\" stroke-width=\"1.7\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/>`\n      + `<path d=\"M9.6 11.6V17H16.4V11.6\" stroke=\"currentColor\" stroke-width=\"1.7\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/>`\n      + `<rect x=\"11.8\" y=\"12.8\" width=\"2.4\" height=\"2.4\" rx=\"0.4\" fill=\"var(--pine,#4E8FD0)\"/>`\n      + `</svg>`;\n  })(),\n  check: `<svg viewBox=\"0 0 16 16\" fill=\"none\"><path d=\"M3 8.5L6.2 11.7L13 4\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></svg>`,\n  checkCircle: `<svg viewBox=\"0 0 20 20\" fill=\"none\"><path d=\"M4 10.5L8 14.5L16 5.5\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></svg>`,\n  arrow: `<svg viewBox=\"0 0 24 12\" fill=\"none\"><path d=\"M0 6H22M22 6L16 1M22 6L16 11\" stroke=\"currentColor\" stroke-width=\"1.6\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></svg>`,\n  home: `<svg viewBox=\"0 0 20 20\" fill=\"none\"><path d=\"M3 9L10 3l7 6M5 8v8h10V8\" stroke=\"currentColor\" stroke-width=\"1.6\" stroke-linejoin=\"round\"/></svg>`,\n  listings: `<svg viewBox=\"0 0 20 20\" fill=\"none\"><rect x=\"3\" y=\"4\" width=\"14\" height=\"4\" rx=\"1\" stroke=\"currentColor\" stroke-width=\"1.6\"/><rect x=\"3\" y=\"12\" width=\"14\" height=\"4\" rx=\"1\" stroke=\"currentColor\" stroke-width=\"1.6\"/></svg>`,\n  studio: `<svg viewBox=\"0 0 20 20\" fill=\"none\"><rect x=\"2.5\" y=\"4\" width=\"15\" height=\"12\" rx=\"2\" stroke=\"currentColor\" stroke-width=\"1.6\"/><circle cx=\"10\" cy=\"10\" r=\"3\" stroke=\"currentColor\" stroke-width=\"1.6\"/></svg>`,\n  credits: `<svg viewBox=\"0 0 20 20\" fill=\"none\"><circle cx=\"10\" cy=\"10\" r=\"7.5\" stroke=\"currentColor\" stroke-width=\"1.6\"/><path d=\"M10 6.5v7M12.3 8.2c0-1-1-1.7-2.3-1.7-1.4 0-2.3.7-2.3 1.6 0 2.3 4.6 1.1 4.6 3.4 0 1-1 1.7-2.3 1.7-1.3 0-2.3-.7-2.3-1.7\" stroke=\"currentColor\" stroke-width=\"1.4\" stroke-linecap=\"round\"/></svg>`,\n  history: `<svg viewBox=\"0 0 20 20\" fill=\"none\"><path d=\"M3.5 10a6.5 6.5 0 1 1 2 4.7\" stroke=\"currentColor\" stroke-width=\"1.6\" stroke-linecap=\"round\"/><path d=\"M2.5 6.5V10H6\" stroke=\"currentColor\" stroke-width=\"1.6\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/><path d=\"M10 6.5V10l2.6 1.6\" stroke=\"currentColor\" stroke-width=\"1.6\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></svg>`,\n  account: `<svg viewBox=\"0 0 20 20\" fill=\"none\"><circle cx=\"10\" cy=\"7\" r=\"3.2\" stroke=\"currentColor\" stroke-width=\"1.6\"/><path d=\"M3.5 16.2c1.2-3 3.6-4.5 6.5-4.5s5.3 1.5 6.5 4.5\" stroke=\"currentColor\" stroke-width=\"1.6\" stroke-linecap=\"round\"/></svg>`,\n  photo: `<svg viewBox=\"0 0 20 20\" fill=\"none\"><rect x=\"2.5\" y=\"3.5\" width=\"15\" height=\"13\" rx=\"2\" stroke=\"currentColor\" stroke-width=\"1.6\"/><circle cx=\"7\" cy=\"8\" r=\"1.6\" stroke=\"currentColor\" stroke-width=\"1.4\"/><path d=\"M4 15l4.5-4.5 3 3 2-2 3.5 3.5\" stroke=\"currentColor\" stroke-width=\"1.5\" stroke-linejoin=\"round\"/></svg>`,\n  video: `<svg viewBox=\"0 0 20 20\" fill=\"none\"><rect x=\"2.5\" y=\"5\" width=\"10.5\" height=\"10\" rx=\"1.6\" stroke=\"currentColor\" stroke-width=\"1.6\"/><path d=\"M13.5 9l4-2.5v7l-4-2.5\" stroke=\"currentColor\" stroke-width=\"1.6\" stroke-linejoin=\"round\"/></svg>`,\n  download: `<svg viewBox=\"0 0 18 18\" fill=\"none\"><path d=\"M9 2.5v9M5.3 8.3L9 12l3.7-3.7\" stroke=\"currentColor\" stroke-width=\"1.6\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/><path d=\"M3 14.5h12\" stroke=\"currentColor\" stroke-width=\"1.6\" stroke-linecap=\"round\"/></svg>`,\n  save: `<svg viewBox=\"0 0 18 18\" fill=\"none\"><rect x=\"3\" y=\"3\" width=\"12\" height=\"12\" rx=\"1.6\" stroke=\"currentColor\" stroke-width=\"1.6\"/><path d=\"M6 3v4h6V3\" stroke=\"currentColor\" stroke-width=\"1.6\"/></svg>`,\n  share: `<svg viewBox=\"0 0 18 18\" fill=\"none\"><circle cx=\"14\" cy=\"4\" r=\"2\" stroke=\"currentColor\" stroke-width=\"1.5\"/><circle cx=\"4\" cy=\"9\" r=\"2\" stroke=\"currentColor\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"2\" stroke=\"currentColor\" stroke-width=\"1.5\"/><path d=\"M5.8 8L12.2 5M5.8 10L12.2 13\" stroke=\"currentColor\" stroke-width=\"1.5\"/></svg>`,\n  again: `<svg viewBox=\"0 0 18 18\" fill=\"none\"><path d=\"M3.5 9a5.5 5.5 0 1 1 1.7 4\" stroke=\"currentColor\" stroke-width=\"1.6\" stroke-linecap=\"round\"/><path d=\"M3 5.5V9h3.5\" stroke=\"currentColor\" stroke-width=\"1.6\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></svg>`,\n  x: `<svg viewBox=\"0 0 16 16\" fill=\"none\"><path d=\"M3 3L13 13M13 3L3 13\" stroke=\"currentColor\" stroke-width=\"1.6\" stroke-linecap=\"round\"/></svg>`,\n  warn: `<svg viewBox=\"0 0 20 20\" fill=\"none\"><path d=\"M10 3.5L18 16.5H2L10 3.5Z\" stroke=\"currentColor\" stroke-width=\"1.6\" stroke-linejoin=\"round\"/><path d=\"M10 8.5v3.4\" stroke=\"currentColor\" stroke-width=\"1.6\" stroke-linecap=\"round\"/><circle cx=\"10\" cy=\"14.3\" r=\".9\" fill=\"currentColor\"/></svg>`,\n};\n\n/* ============================================================\n   ROOM ILLUSTRATIONS\n   Flat, elevation-style line art. Layers toggle by CSS state\n   classes; palette swaps entirely through CSS variables so one\n   markup template renders every staging style / twilight mood.\n   ============================================================ */\nfunction svgOpen(id){\n  return `<svg viewBox=\"0 0 640 480\" preserveAspectRatio=\"xMidYMid slice\" xmlns=\"http://www.w3.org/2000/svg\">\n  <defs>\n    <linearGradient id=\"skyGrad${id}\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\">\n      <stop offset=\"0%\" stop-color=\"var(--sky1,#dbe6e0)\"/>\n      <stop offset=\"55%\" stop-color=\"var(--sky2,#c7d6cd)\"/>\n      <stop offset=\"100%\" stop-color=\"var(--sky3,#b7c9bd)\"/>\n    </linearGradient>\n    <linearGradient id=\"floorGrad${id}\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\">\n      <stop offset=\"0%\" stop-color=\"#EFE8D8\"/>\n      <stop offset=\"100%\" stop-color=\"#E0D6BC\"/>\n    </linearGradient>\n  </defs>`;\n}\nfunction livingRoom(id){\n  return svgOpen(id)+`\n  <rect width=\"640\" height=\"480\" fill=\"#F4EFE3\"/>\n  <rect x=\"0\" y=\"330\" width=\"640\" height=\"150\" fill=\"url(#floorGrad${id})\"/>\n  <rect x=\"0\" y=\"330\" width=\"640\" height=\"4\" fill=\"#D8CBA9\"/>\n  <g class=\"architecture\">\n    <rect x=\"60\" y=\"70\" width=\"180\" height=\"200\" fill=\"#fff\" stroke=\"#C9BF9F\" stroke-width=\"3\"/>\n    <path d=\"M150 70V270M60 170H240\" stroke=\"#C9BF9F\" stroke-width=\"3\"/>\n    <rect x=\"430\" y=\"80\" width=\"150\" height=\"250\" fill=\"none\" stroke=\"#C9BF9F\" stroke-width=\"3\"/>\n    <rect x=\"440\" y=\"90\" width=\"55\" height=\"70\" fill=\"none\" stroke=\"#E3DAC2\" stroke-width=\"2\"/>\n  </g>\n  <g class=\"clutter\">\n    <rect x=\"90\" y=\"300\" width=\"70\" height=\"55\" rx=\"3\" fill=\"#C9B98C\"/>\n    <path d=\"M90 320h70\" stroke=\"#A9976B\" stroke-width=\"2\"/>\n    <rect x=\"175\" y=\"315\" width=\"55\" height=\"40\" rx=\"3\" fill=\"#B7C4B4\"/>\n    <ellipse cx=\"330\" cy=\"345\" rx=\"46\" ry=\"20\" fill=\"#D9A98C\"/>\n    <path d=\"M292 340q38-26 76 0\" stroke=\"#B8805F\" stroke-width=\"3\" fill=\"none\"/>\n    <rect x=\"360\" y=\"290\" width=\"34\" height=\"66\" rx=\"4\" fill=\"#9AA6A0\"/>\n    <circle cx=\"377\" cy=\"360\" r=\"12\" fill=\"#7C8985\"/>\n    <rect x=\"440\" y=\"310\" width=\"24\" height=\"46\" fill=\"#B0A484\"/>\n    <rect x=\"470\" y=\"300\" width=\"24\" height=\"56\" fill=\"#9E9478\"/>\n    <rect x=\"500\" y=\"320\" width=\"24\" height=\"36\" fill=\"#C4B896\"/>\n  </g>\n  <g class=\"staged\">\n    <rect x=\"270\" y=\"280\" width=\"200\" height=\"70\" rx=\"14\" fill=\"var(--a,#33383F)\"/>\n    <rect x=\"278\" y=\"270\" width=\"55\" height=\"26\" rx=\"10\" fill=\"var(--b,#CDC5B2)\"/>\n    <rect x=\"405\" y=\"270\" width=\"55\" height=\"26\" rx=\"10\" fill=\"var(--b,#CDC5B2)\"/>\n    <rect x=\"300\" y=\"360\" width=\"120\" height=\"8\" rx=\"4\" fill=\"var(--c,#8B8F86)\"/>\n    <rect x=\"150\" y=\"330\" width=\"220\" height=\"14\" rx=\"7\" fill=\"var(--b,#CDC5B2)\" opacity=\"0.55\"/>\n    <rect x=\"490\" y=\"270\" width=\"14\" height=\"90\" fill=\"var(--c,#8B8F86)\"/>\n    <ellipse cx=\"497\" cy=\"262\" rx=\"26\" ry=\"10\" fill=\"var(--c,#8B8F86)\" opacity=\"0.7\"/>\n    <rect x=\"330\" y=\"150\" width=\"60\" height=\"80\" fill=\"none\" stroke=\"#A97A38\" stroke-width=\"3\"/>\n    <rect x=\"336\" y=\"156\" width=\"48\" height=\"68\" fill=\"var(--b,#CDC5B2)\" opacity=\"0.4\"/>\n  </g>\n  </svg>`;\n}\nfunction bedroom(id){\n  return svgOpen(id)+`\n  <rect width=\"640\" height=\"480\" fill=\"#F4EFE3\"/>\n  <rect x=\"0\" y=\"340\" width=\"640\" height=\"140\" fill=\"url(#floorGrad${id})\"/>\n  <rect x=\"0\" y=\"340\" width=\"640\" height=\"4\" fill=\"#D8CBA9\"/>\n  <g class=\"architecture\">\n    <rect x=\"420\" y=\"70\" width=\"170\" height=\"200\" fill=\"#fff\" stroke=\"#C9BF9F\" stroke-width=\"3\"/>\n    <path d=\"M505 70V270M420 170H590\" stroke=\"#C9BF9F\" stroke-width=\"3\"/>\n  </g>\n  <g class=\"clutter\">\n    <rect x=\"70\" y=\"290\" width=\"90\" height=\"60\" rx=\"4\" fill=\"#C9B98C\"/>\n    <rect x=\"180\" y=\"300\" width=\"70\" height=\"50\" rx=\"4\" fill=\"#B7A48C\"/>\n    <path d=\"M70 316h90M180 320h70\" stroke=\"#9C8A66\" stroke-width=\"2\"/>\n    <ellipse cx=\"330\" cy=\"345\" rx=\"50\" ry=\"18\" fill=\"#CBB6A5\"/>\n    <rect x=\"290\" y=\"270\" width=\"90\" height=\"50\" rx=\"20\" fill=\"#B58F7A\"/>\n  </g>\n  <g class=\"staged\">\n    <rect x=\"230\" y=\"220\" width=\"220\" height=\"120\" rx=\"10\" fill=\"var(--a,#5B4636)\"/>\n    <path d=\"M240 220v-40q100-30 200 0v40\" fill=\"var(--a,#5B4636)\"/>\n    <ellipse cx=\"290\" cy=\"235\" rx=\"30\" ry=\"18\" fill=\"var(--b,#E7DEC7)\"/>\n    <ellipse cx=\"390\" cy=\"235\" rx=\"30\" ry=\"18\" fill=\"var(--b,#E7DEC7)\"/>\n    <rect x=\"240\" y=\"290\" width=\"200\" height=\"16\" fill=\"var(--b,#E7DEC7)\" opacity=\"0.7\"/>\n    <rect x=\"130\" y=\"290\" width=\"60\" height=\"50\" rx=\"5\" fill=\"var(--c,#A98B5E)\"/>\n    <rect x=\"480\" y=\"290\" width=\"60\" height=\"50\" rx=\"5\" fill=\"var(--c,#A98B5E)\"/>\n    <ellipse cx=\"330\" cy=\"370\" rx=\"150\" ry=\"24\" fill=\"var(--c,#A98B5E)\" opacity=\"0.5\"/>\n  </g>\n  </svg>`;\n}\nfunction diningRoom(id){\n  return svgOpen(id)+`\n  <rect width=\"640\" height=\"480\" fill=\"#F4EFE3\"/>\n  <rect x=\"0\" y=\"340\" width=\"640\" height=\"140\" fill=\"url(#floorGrad${id})\"/>\n  <rect x=\"0\" y=\"340\" width=\"640\" height=\"4\" fill=\"#D8CBA9\"/>\n  <g class=\"architecture\">\n    <rect x=\"60\" y=\"80\" width=\"150\" height=\"190\" fill=\"#fff\" stroke=\"#C9BF9F\" stroke-width=\"3\"/>\n    <path d=\"M135 80V270\" stroke=\"#C9BF9F\" stroke-width=\"3\"/>\n  </g>\n  <g class=\"clutter\">\n    <rect x=\"260\" y=\"300\" width=\"140\" height=\"18\" rx=\"6\" fill=\"#C9B98C\"/>\n    <rect x=\"270\" y=\"270\" width=\"120\" height=\"30\" rx=\"4\" fill=\"#B7A48C\"/>\n    <rect x=\"440\" y=\"310\" width=\"60\" height=\"40\" rx=\"4\" fill=\"#9AA6A0\"/>\n  </g>\n  <g class=\"staged\">\n    <ellipse cx=\"330\" cy=\"300\" rx=\"120\" ry=\"34\" fill=\"var(--a,#5B4636)\"/>\n    <rect x=\"230\" y=\"270\" width=\"14\" height=\"70\" fill=\"var(--c,#A98B5E)\"/>\n    <rect x=\"420\" y=\"270\" width=\"14\" height=\"70\" fill=\"var(--c,#A98B5E)\"/>\n    <rect x=\"250\" y=\"260\" width=\"16\" height=\"50\" fill=\"var(--b,#E7DEC7)\"/>\n    <rect x=\"400\" y=\"260\" width=\"16\" height=\"50\" fill=\"var(--b,#E7DEC7)\"/>\n    <path d=\"M330 130v90\" stroke=\"#A97A38\" stroke-width=\"3\"/>\n    <path d=\"M300 220h60l-30 30z\" fill=\"#A97A38\"/>\n  </g>\n  </svg>`;\n}\nfunction officeRoom(id){\n  return svgOpen(id)+`\n  <rect width=\"640\" height=\"480\" fill=\"#F4EFE3\"/>\n  <rect x=\"0\" y=\"340\" width=\"640\" height=\"140\" fill=\"url(#floorGrad${id})\"/>\n  <rect x=\"0\" y=\"340\" width=\"640\" height=\"4\" fill=\"#D8CBA9\"/>\n  <g class=\"architecture\">\n    <rect x=\"440\" y=\"80\" width=\"150\" height=\"190\" fill=\"#fff\" stroke=\"#C9BF9F\" stroke-width=\"3\"/>\n    <path d=\"M515 80V270\" stroke=\"#C9BF9F\" stroke-width=\"3\"/>\n  </g>\n  <g class=\"clutter\">\n    <rect x=\"120\" y=\"290\" width=\"130\" height=\"60\" rx=\"4\" fill=\"#C9B98C\"/>\n    <rect x=\"270\" y=\"300\" width=\"70\" height=\"50\" rx=\"4\" fill=\"#B7A48C\"/>\n  </g>\n  <g class=\"staged\">\n    <rect x=\"140\" y=\"270\" width=\"160\" height=\"14\" fill=\"var(--a,#33383F)\"/>\n    <rect x=\"150\" y=\"284\" width=\"14\" height=\"56\" fill=\"var(--a,#33383F)\"/>\n    <rect x=\"276\" y=\"284\" width=\"14\" height=\"56\" fill=\"var(--a,#33383F)\"/>\n    <rect x=\"330\" y=\"230\" width=\"70\" height=\"110\" fill=\"var(--c,#8B8F86)\" opacity=\"0.25\"/>\n    <rect x=\"330\" y=\"230\" width=\"70\" height=\"4\" fill=\"var(--c,#8B8F86)\"/>\n    <rect x=\"330\" y=\"270\" width=\"70\" height=\"4\" fill=\"var(--c,#8B8F86)\"/>\n    <rect x=\"330\" y=\"310\" width=\"70\" height=\"4\" fill=\"var(--c,#8B8F86)\"/>\n    <path d=\"M195 260q25-30 50 0\" stroke=\"var(--b,#CDC5B2)\" stroke-width=\"10\" fill=\"none\" stroke-linecap=\"round\"/>\n  </g>\n  </svg>`;\n}\nfunction exterior(id){\n  return svgOpen(id)+`\n  <rect width=\"640\" height=\"480\" class=\"sky-fill\" fill=\"url(#skyGrad${id})\"/>\n  <rect x=\"0\" y=\"360\" width=\"640\" height=\"120\" fill=\"#8CA37E\"/>\n  <path d=\"M0 360 L640 360\" stroke=\"#7A9270\" stroke-width=\"2\"/>\n  <g class=\"glow-elems\">\n  <path d=\"M260 200 L330 130 L400 200 Z\" fill=\"#EFE6D2\" stroke=\"#C9BF9F\" stroke-width=\"3\"/>\n  <rect x=\"260\" y=\"200\" width=\"140\" height=\"140\" fill=\"#F4EFE3\" stroke=\"#C9BF9F\" stroke-width=\"3\"/>\n  <rect x=\"285\" y=\"230\" width=\"34\" height=\"34\" fill=\"var(--win-fill,#BFD2E0)\" stroke=\"#C9BF9F\" stroke-width=\"2\"/>\n  <rect x=\"341\" y=\"230\" width=\"34\" height=\"34\" fill=\"var(--win-fill,#BFD2E0)\" stroke=\"#C9BF9F\" stroke-width=\"2\"/>\n  <rect x=\"313\" y=\"285\" width=\"34\" height=\"55\" fill=\"var(--door-fill,#5B4636)\" stroke=\"#C9BF9F\" stroke-width=\"2\"/>\n  <path d=\"M240 340 L420 340 L440 480 L220 480 Z\" fill=\"#D8CBA9\"/>\n  <circle cx=\"500\" cy=\"300\" r=\"26\" fill=\"#7C9A6E\"/>\n  <rect x=\"494\" y=\"300\" width=\"12\" height=\"60\" fill=\"#8A6E4E\"/>\n  <circle cx=\"140\" cy=\"310\" r=\"20\" fill=\"#7C9A6E\"/>\n  <rect x=\"135\" y=\"310\" width=\"10\" height=\"50\" fill=\"#8A6E4E\"/>\n  </g>\n  <g class=\"clutter\">\n    <ellipse cx=\"330\" cy=\"475\" rx=\"6\" ry=\"3\" fill=\"#00000022\"/>\n  </g>\n  <g class=\"glow-lights\" opacity=\"0\">\n    <circle cx=\"302\" cy=\"247\" r=\"20\" fill=\"var(--glow,#FFD37E)\" opacity=\"0.55\"/>\n    <circle cx=\"358\" cy=\"247\" r=\"20\" fill=\"var(--glow,#FFD37E)\" opacity=\"0.55\"/>\n    <circle cx=\"330\" cy=\"312\" r=\"18\" fill=\"var(--glow,#FFD37E)\" opacity=\"0.5\"/>\n    <circle cx=\"250\" cy=\"420\" r=\"5\" fill=\"var(--glow,#FFD37E)\"/>\n    <circle cx=\"410\" cy=\"420\" r=\"5\" fill=\"var(--glow,#FFD37E)\"/>\n  </g>\n  </svg>`;\n}\nconst ROOM_BUILDERS = { living:livingRoom, bedroom:bedroom, dining:diningRoom, office:officeRoom, exterior:exterior };\n\nlet roomSvgCounter=0;\n/**\n * Renders a room illustration.\n * type: living|bedroom|dining|office|exterior\n * state: before|after|empty|day|twilight\n * opts: {style, time}\n */\nfunction room(type, state, opts){\n  opts = opts||{};\n  roomSvgCounter++;\n  const id='r'+roomSvgCounter;\n  const builder = ROOM_BUILDERS[type] || livingRoom;\n  const stateClass = type==='exterior'\n    ? (state==='twilight' ? 'state-after' : 'state-before')\n    : (state==='before' ? 'state-before' : state==='empty' ? 'state-empty' : 'state-after');\n  const styleClass = opts.style ? ('style-'+(STYLE_CLASS[opts.style]||'modern')) : '';\n  // The room's *state* decides day vs. twilight — never the shared opts object —\n  // so a before/after pair never accidentally paints the same sky on both sides.\n  const timeClass = type==='exterior'\n    ? (state==='twilight' ? ('time-'+(TIME_CLASS[opts.time]||'golden')) : 'time-day')\n    : '';\n  let svg = builder(id);\n  if(type==='exterior'){\n    const twilightOn = state==='twilight';\n    svg = svg.replace('opacity=\"0\"', twilightOn?'opacity=\"1\"':'opacity=\"0\"');\n    if(twilightOn){\n      svg = svg.replace(/var\\(--win-fill,#BFD2E0\\)/g,'var(--glow,#FFD37E)');\n    }\n  }\n  return `<div class=\"room ${stateClass} ${styleClass} ${timeClass}\">${svg}</div>`;\n}\n\n/* ============================================================\n   TOASTS\n   ============================================================ */\nfunction toast(msg){\n  const root = document.getElementById('toast-root');\n  const el = document.createElement('div');\n  el.className='toast';\n  el.innerHTML = ICON.checkCircle + `<span>${msg}</span>`;\n  root.appendChild(el);\n  setTimeout(()=>{ el.style.opacity='0'; el.style.transition='opacity .3s ease'; setTimeout(()=>el.remove(),320); }, 2600);\n}\n\n/* ============================================================\n   ROUTER\n   ============================================================ */\nfunction go(hash){ location.hash = hash; }\nwindow.addEventListener('hashchange', render);\nwindow.addEventListener('DOMContentLoaded', render);\n\nfunction parseRoute(){\n  const raw = location.hash.replace(/^#\\/?/,'');\n  const seg = raw.split('/').filter(Boolean);\n  return seg;\n}\n\nconst IN_PAGE_ANCHORS = ['how','compliance','pricing'];\nfunction render(){\n  const rawHash = location.hash.replace(/^#\\/?/,'');\n  if(IN_PAGE_ANCHORS.includes(rawHash)) return; // same-page anchor — let native scroll happen, don't rebuild the DOM\n  const seg = ['admin']; // standalone internal tool — always the dashboard\n  const app = document.getElementById('app');\n  window.scrollTo(0,0);\n  if(seg[0] === 'admin'){\n    app.innerHTML = renderAdminShell();\n    afterAdminRender();\n    return;\n  }\n  if(seg[0] !== 'app'){\n    app.innerHTML = renderMarketing();\n    afterMarketingRender();\n    return;\n  }\n  // app shell\n  let body = '';\n  let crumbs = [];\n  if(seg.length===1){ body = renderDashboard(); crumbs=[{label:'Dashboard'}]; }\n  else if(seg[1]==='listings'){ body = renderListingsGallery(); crumbs=[{label:'Listings'}]; }\n  else if(seg[1]==='credits'){ body = renderCredits(); crumbs=[{label:'Credits'}]; }\n  else if(seg[1]==='history'){ body = renderHistory(); crumbs=[{label:'History'}]; }\n  else if(seg[1]==='account'){ body = renderAccount(); crumbs=[{label:'Account'}]; }\n  else if(seg[1]==='listing'){\n    const listingId = seg[2];\n    const listing = getListing(listingId);\n    if(!listing){ body = renderNotFound(); }\n    else if(seg.length===3){ body = renderListingDetail(listing); crumbs=[{label:'Listings',href:'#/app/listings'},{label:listing.addr}]; }\n    else if(seg[3]==='photo'){\n      const photoId = seg[4];\n      const photo = getPhoto(listingId, photoId);\n      if(!photo){ body = renderNotFound(); }\n      else if(seg.length===5){ body = renderPhotoViewer(listing, photo); crumbs=[{label:'Listings',href:'#/app/listings'},{label:listing.addr,href:'#/app/listing/'+listing.id},{label:photo.room}]; }\n      else if(seg[5]==='studio'){ body = renderStudio(listing, photo); crumbs=[{label:'Listings',href:'#/app/listings'},{label:listing.addr,href:'#/app/listing/'+listing.id},{label:photo.room,href:'#/app/listing/'+listing.id+'/photo/'+photo.id},{label:'AI Studio'}]; }\n      else if(seg[5]==='result'){\n        const resultId = seg[6];\n        const result = S.results[resultId];\n        if(!result){ body = renderNotFound(); }\n        else{ body = renderResult(listing, photo, result); crumbs=[{label:'Listings',href:'#/app/listings'},{label:listing.addr,href:'#/app/listing/'+listing.id},{label:photo.room,href:'#/app/listing/'+listing.id+'/photo/'+photo.id},{label:'Result'}]; }\n      }\n    }\n  }\n  if(!body) body = renderNotFound();\n  app.innerHTML = renderAppShell(body, crumbs, seg);\n  afterAppRender(seg);\n}\n\n/* ============================================================\n   MARKETING PAGE\n   ============================================================ */\nfunction renderMarketing(){\n  return `\n  <div class=\"site\">\n    ${siteNav()}\n    ${hero()}\n    ${marquee()}\n    ${complianceSection()}\n    ${capabilitySections()}\n    ${pricingSection()}\n    ${finalCta()}\n    ${siteFooter()}\n  </div>`;\n}\n\nfunction siteNav(){\n  return `\n  <header class=\"site-nav\">\n    <div class=\"wrap site-nav-row\">\n      <a href=\"#/\" class=\"mark\">${ICON.logoMark}<span>Listing&nbsp;<span class=\"lab\">Lab</span></span></a>\n      <nav class=\"site-nav-links\">\n        <a href=\"#how\">Capabilities</a>\n        <a href=\"#compliance\">Compliance</a>\n        <a href=\"#pricing\">Pricing</a>\n      </nav>\n      <div class=\"site-nav-cta\">\n        <a href=\"#/app\" class=\"btn btn-quiet\">Sign In</a>\n        <a href=\"#/app\" class=\"btn btn-primary btn-sm\">Try Listing Lab</a>\n      </div>\n    </div>\n  </header>`;\n}\n\nfunction hero(){\n  return `\n  <section class=\"hero\">\n    <div class=\"wrap hero-grid\">\n      <div class=\"reveal\">\n        <div class=\"eyebrow hero-eyebrow\">Horizon Home Media &nbsp;·&nbsp; AI Post-Production</div>\n        <h1>Professional AI finishing for real-estate photography.</h1>\n        <p class=\"hero-sub\">Transform your listing photography with controlled, photorealistic AI editing built specifically for real estate — every image reviewed by an automatic compliance check before it reaches your listing.</p>\n        <div class=\"hero-cta\">\n          <a href=\"#/app\" class=\"btn btn-primary\">Try Listing Lab</a>\n          <a href=\"#compliance\" class=\"btn btn-ghost\">See How It Works</a>\n        </div>\n        <div class=\"hero-proof\">\n          <div class=\"hero-proof-item\"><b>3</b>Approved AI transformations, nothing arbitrary</div>\n          <div class=\"hero-proof-item\"><b>100%</b>Of deliveries pass an automated compliance check</div>\n          <div class=\"hero-proof-item\"><b>&lt;60s</b>From photo to finished, watermarked result</div>\n        </div>\n      </div>\n      <div class=\"reveal\" style=\"animation-delay:.1s\">\n        ${beforeAfter('living','before','after', {style:'Luxury'}, 'Original', 'Declutter')}\n      </div>\n    </div>\n  </section>`;\n}\n\nfunction beforeAfter(type, beforeState, afterState, opts, beforeTag, afterTag){\n  const bid = 'ba'+(++roomSvgCounter);\n  return `\n  <div class=\"ba\" id=\"${bid}\">\n    <div class=\"ba-layer ba-before\">${room(type, beforeState, opts)}</div>\n    <div class=\"ba-layer ba-after\">${room(type, afterState, opts)}</div>\n    <div class=\"ba-tag tag-before\">${beforeTag||'Before'}</div>\n    <div class=\"ba-tag tag-after\">${afterTag||'After'}</div>\n    <div class=\"ba-handle\" data-ba=\"${bid}\"><div class=\"ba-knob\">${ICON.arrow}</div></div>\n  </div>`;\n}\n\nfunction marquee(){\n  const items=['Declutter','Virtual Staging','Twilight','Compliance-Checked','Watermarked Automatically','Never Overwrites the Original'];\n  return `<div class=\"marquee\"><div class=\"wrap\" style=\"display:flex;gap:48px;\">${items.concat(items).map(i=>`<span>${i}</span>`).join('<span style=\"color:var(--brass)\">&middot;</span>')}</div></div>`;\n}\n\nfunction complianceSection(){\n  const steps=[\n    {n:1,t:'Approved Transformation',d:'The agent picks from a closed set of edits — never an open prompt.'},\n    {n:2,t:'AI Generation',d:'Nano Banana Pro renders the transformation inside strict guardrails.'},\n    {n:3,t:'Compliance Check',d:'The result is verified against the rules for that transformation.'},\n    {n:4,t:'Disclosure',d:'A required watermark is applied automatically — it cannot be turned off.'},\n    {n:5,t:'Delivery',d:'Only a passing, watermarked image is ever released to the listing.'},\n  ];\n  return `\n  <section class=\"section\" id=\"compliance\">\n    <div class=\"wrap\">\n      <div class=\"compliance-band\">\n        <div class=\"section-head\">\n          <div class=\"eyebrow\" style=\"color:var(--brass)\">Product Philosophy</div>\n          <h2>AI with guardrails.</h2>\n          <p>Powerful enough to transform your listing photos. Controlled enough to protect the integrity of the property.</p>\n        </div>\n        <div class=\"flow\">\n          ${steps.map((s,i)=>`\n            <div class=\"flow-step reveal\" style=\"animation-delay:${i*0.06}s\"><div class=\"flow-num\">${s.n}</div><h4>${s.t}</h4><p>${s.d}</p></div>\n            ${i<steps.length-1?`<div class=\"flow-connector\">${ICON.arrow}</div>`:''}\n          `).join('')}\n        </div>\n      </div>\n    </div>\n  </section>`;\n}\n\nfunction capabilitySections(){\n  return `\n  <section class=\"wrap\" id=\"how\">\n    <div class=\"section-head\" style=\"margin-bottom:0;\">\n      <div class=\"eyebrow\">Capabilities</div>\n      <h2>Three transformations. Zero guesswork.</h2>\n      <p>No prompt box. No free-form editing. Just the AI real estate professionals actually need, delivered with control.</p>\n    </div>\n    <div class=\"capability\">\n      <div class=\"capability-copy reveal\">\n        <div class=\"cap-index\">01 — Declutter</div>\n        <h3>Clean the room. Keep the property.</h3>\n        <p>Removes movable clutter — boxes, laundry, loose furniture — while architecture, fixtures, floors and perspective stay exactly as photographed.</p>\n        <div class=\"cap-points\">\n          <div class=\"cap-point\">${ICON.check}Preserves walls, windows, floors and built-ins</div>\n          <div class=\"cap-point\">${ICON.check}Removes only appropriate movable objects</div>\n        </div>\n        <div class=\"cap-credit\"><b>1 credit</b>&nbsp;per photo</div>\n      </div>\n      <div class=\"reveal\">${beforeAfter('living','before','after',{style:'Modern'},'Original','Decluttered')}</div>\n    </div>\n    <div class=\"capability\">\n      <div class=\"capability-copy reveal\">\n        <div class=\"cap-index\">02 — Virtual Staging</div>\n        <h3>Stage empty rooms in seconds.</h3>\n        <p>Photorealistic, tasteful furniture in five controlled styles — added without ever changing architecture, dimensions or perspective.</p>\n        <div class=\"cap-points\">\n          <div class=\"cap-point\">${ICON.check}Modern, Transitional, Contemporary, Coastal, Luxury</div>\n          <div class=\"cap-point\">${ICON.check}Structural features always preserved</div>\n        </div>\n        <div class=\"cap-credit\"><b>2 credits</b>&nbsp;per photo</div>\n      </div>\n      <div class=\"reveal\">${beforeAfter('bedroom','empty','after',{style:'Coastal'},'Empty','Staged · Coastal')}</div>\n    </div>\n    <div class=\"capability\">\n      <div class=\"capability-copy reveal\">\n        <div class=\"cap-index\">03 — Twilight</div>\n        <h3>Turn daylight into golden hour.</h3>\n        <p>A professional daylight exterior becomes a realistic dusk photograph — lighting and sky only, property untouched.</p>\n        <div class=\"cap-points\">\n          <div class=\"cap-point\">${ICON.check}Golden Hour, Dusk, or Blue Hour</div>\n          <div class=\"cap-point\">${ICON.check}Architecture, landscaping and proportions preserved</div>\n        </div>\n        <div class=\"cap-credit\"><b>1 credit</b>&nbsp;per photo</div>\n      </div>\n      <div class=\"reveal\">${beforeAfter('exterior','day','twilight',{time:'Golden Hour'},'Daylight','Golden Hour')}</div>\n    </div>\n  </section>`;\n}\n\nfunction pricingSection(){\n  return `\n  <section class=\"section\" id=\"pricing\">\n    <div class=\"wrap\">\n      <div class=\"section-head\">\n        <div class=\"eyebrow\">Pricing</div>\n        <h2>Simple, credit-based pricing.</h2>\n        <p>Pay for finished, compliance-checked results — never for a generation you can't use.</p>\n      </div>\n      <div class=\"pricing-grid\">\n        ${PACKS.map(p=>`\n          <div class=\"card price-card ${p.best?'featured':''}\">\n            ${p.best?'<div class=\"featured-tag\">Most Popular</div>':''}\n            <h4>${p.credits} Credits</h4>\n            <div class=\"price-num\">$${p.price.toFixed(2)}</div>\n            <div class=\"price-credits\">$${(p.price/p.credits).toFixed(2)} per credit</div>\n            <ul class=\"price-list\">\n              <li>${ICON.check}<span>${Math.floor(p.credits/1)} Declutter or Twilight edits</span></li>\n              <li>${ICON.check}<span>${Math.floor(p.credits/2)} Virtual Staging edits</span></li>\n              <li>${ICON.check}<span>Unused credits never expire</span></li>\n            </ul>\n            <a href=\"#/app\" class=\"btn btn-ghost btn-block\">Try Listing Lab</a>\n          </div>\n        `).join('')}\n      </div>\n    </div>\n  </section>`;\n}\n\nfunction finalCta(){\n  return `\n  <section class=\"section\" style=\"padding-top:0;\">\n    <div class=\"wrap\" style=\"text-align:center;background:var(--paper-2);border:1px solid var(--line);border-radius:var(--r-xl);padding:72px 40px;\">\n      <h2 style=\"font-size:clamp(1.9rem,3.5vw,2.6rem);\">Ready to see your listings finished?</h2>\n      <p style=\"margin-top:16px;color:var(--ink-soft);max-width:48ch;margin-left:auto;margin-right:auto;\">Open the studio, pick a transformation, and let the compliance engine do the rest.</p>\n      <div class=\"hero-cta\" style=\"justify-content:center;margin-top:30px;\">\n        <a href=\"#/app\" class=\"btn btn-primary\">Try Listing Lab</a>\n      </div>\n    </div>\n  </section>`;\n}\n\nfunction siteFooter(){\n  return `\n  <footer class=\"site-footer\">\n    <div class=\"wrap\">\n      <div class=\"footer-grid\">\n        <div>\n          <div class=\"mark\" style=\"color:#fff;\">${ICON.logoMark}<span>Listing&nbsp;<span class=\"lab\">Lab</span></span></div>\n          <p style=\"margin-top:14px;font-size:0.87rem;max-width:32ch;color:#96A2B0;\">A Horizon Home Media product. Professional AI finishing for real-estate photography — built for the photographers whose name is on the image.</p>\n        </div>\n        <div><h5>Product</h5><ul><li><a href=\"#how\">Capabilities</a></li><li><a href=\"#compliance\">Compliance</a></li><li><a href=\"#pricing\">Pricing</a></li></ul></div>\n        <div><h5>Studio</h5><ul><li><a href=\"#/app\">AI Studio</a></li><li><a href=\"#/app/listings\">Listings</a></li><li><a href=\"#/app/credits\">Credits</a></li></ul></div>\n        <div><h5>Company</h5><ul><li>Horizon Home Media</li><li>Support</li><li>Status</li><li><a href=\"#/admin\">Owner Dashboard</a></li></ul></div>\n      </div>\n      <div class=\"footer-bottom\">\n        <span>© 2026 Horizon Home Media. All rights reserved.</span>\n        <span>Every AI derivative is disclosed. Originals are never overwritten.</span>\n      </div>\n    </div>\n  </footer>`;\n}\n\nfunction afterMarketingRender(){\n  bindBeforeAfterSliders();\n}\n\nfunction bindBeforeAfterSliders(){\n  document.querySelectorAll('.ba').forEach(baEl=>{\n    let dragging=false;\n    const setPos = (clientX)=>{\n      const rect = baEl.getBoundingClientRect();\n      let pct = ((clientX-rect.left)/rect.width)*100;\n      pct = Math.max(4,Math.min(96,pct));\n      baEl.style.setProperty('--ba-pos', pct+'%');\n    };\n    baEl.addEventListener('pointerdown', e=>{ dragging=true; setPos(e.clientX); baEl.setPointerCapture(e.pointerId); });\n    baEl.addEventListener('pointermove', e=>{ if(dragging) setPos(e.clientX); });\n    baEl.addEventListener('pointerup', ()=>dragging=false);\n    baEl.addEventListener('pointerleave', ()=>dragging=false);\n  });\n}\n\nfunction renderNotFound(){\n  return `<div class=\"empty-state\"><h3 style=\"color:inherit;\">Not found</h3><p style=\"margin-top:10px;\">That page doesn't exist in the prototype.</p><a href=\"#/app\" class=\"btn btn-primary\" style=\"margin-top:20px;\">Back to Dashboard</a></div>`;\n}\n\n/* ============================================================\n   APP SHELL\n   ============================================================ */\nfunction renderAppShell(body, crumbs, seg){\n  const nav = [\n    {href:'#/app', label:'Dashboard', icon:ICON.home, match:s=>s.length===1},\n    {href:'#/app/listings', label:'Listings', icon:ICON.listings, match:s=>s[1]==='listings'||s[1]==='listing'},\n    {href:'#/app/credits', label:'Credits', icon:ICON.credits, match:s=>s[1]==='credits'},\n    {href:'#/app/history', label:'History', icon:ICON.history, match:s=>s[1]==='history'},\n    {href:'#/app/account', label:'Account', icon:ICON.account, match:s=>s[1]==='account'},\n  ];\n  return `\n  <div class=\"studio\">\n    <div class=\"studio-topbar\">\n      <div class=\"wrap studio-topbar-row\">\n        <a href=\"#/\" class=\"mark\">${ICON.logoMark}<span>Listing&nbsp;<span class=\"lab\">Lab</span></span></a>\n        <nav class=\"studio-nav\">\n          ${nav.map(n=>`<a href=\"${n.href}\" class=\"${n.match(seg)?'active':''}\">${n.icon}<span class=\"nav-label\">${n.label}</span></a>`).join('')}\n        </nav>\n        <a href=\"#/app/credits\" class=\"credit-chip\">${ICON.credits}<span>${S.credits} Credits</span></a>\n      </div>\n    </div>\n    <div class=\"wrap\">\n      ${crumbs && crumbs.length ? `<div class=\"crumbs\">${crumbs.map((c,i)=>`${i>0?'<span class=\\\"sep\\\">/</span>':''}${c.href?`<a href=\"${c.href}\">${c.label}</a>`:`<span class=\"current\">${c.label}</span>`}`).join('')}</div>`:''}\n      <div class=\"reveal\" style=\"padding-bottom:80px;\">${body}</div>\n    </div>\n  </div>`;\n}\n\nfunction afterAppRender(seg){\n  bindBeforeAfterSliders();\n  bindStudioInteractions(seg);\n}\n\n/* ---------- Dashboard ---------- */\nfunction renderDashboard(){\n  const recentTransforms = S.history.slice(0,4);\n  return `\n  <div class=\"page-head\">\n    <div><h1>Welcome back</h1><p>Here's what's happening across your listings.</p></div>\n    <a href=\"#/app/listing/${S.listings[0].id}/photo/${S.listings[0].photos[0].id}/studio\" class=\"btn btn-primary\">Open AI Studio</a>\n  </div>\n  <div class=\"stat-row\">\n    <div class=\"card stat-card\"><div class=\"stat-label\">Credits Remaining</div><div class=\"stat-value\">${S.credits}</div><div class=\"stat-sub\"><a href=\"#/app/credits\" style=\"color:var(--studio-pine);font-weight:600;\">Buy more credits →</a></div></div>\n    <div class=\"card stat-card\"><div class=\"stat-label\">Active Listings</div><div class=\"stat-value\">${S.listings.length}</div><div class=\"stat-sub\">${S.listings.reduce((a,l)=>a+l.photos.length,0)} photos total</div></div>\n    <div class=\"card stat-card\"><div class=\"stat-label\">Transformations Approved</div><div class=\"stat-value\">${S.history.filter(h=>h.status==='approved').length}</div><div class=\"stat-sub\">${S.history.filter(h=>h.status==='rejected').length} rejected &amp; refunded</div></div>\n  </div>\n  <div style=\"display:grid;grid-template-columns:1.3fr 1fr;gap:22px;\" class=\"dash-grid\">\n  <style>@media(max-width:900px){.dash-grid{grid-template-columns:1fr !important;}}</style>\n    <div class=\"card\" style=\"padding:26px 28px;\">\n      <div style=\"display:flex;align-items:center;justify-content:space-between;margin-bottom:6px;\"><h3 style=\"font-size:1.15rem;color:var(--studio-text);\">Recent Listings</h3><a href=\"#/app/listings\" style=\"font-size:0.85rem;color:var(--studio-pine);font-weight:600;\">View all</a></div>\n      <div>\n        ${S.listings.map(l=>`\n          <div class=\"recent-row\" style=\"cursor:pointer;\" onclick=\"LL.go('#/app/listing/${l.id}')\">\n            <div class=\"recent-thumb\">${room(l.photos[0].type, l.photos[0].type==='exterior'?'twilight':(l.photos[0].beforeState==='before'?'after':'after'), {style:'Luxury', time:'Golden Hour'})}</div>\n            <div class=\"recent-body\"><div class=\"r-title\">${l.addr}</div><div class=\"r-sub\">${l.city} · ${l.photos.length} photos</div></div>\n            ${ICON.arrow}\n          </div>\n        `).join('')}\n      </div>\n    </div>\n    <div class=\"card\" style=\"padding:26px 28px;\">\n      <h3 style=\"font-size:1.15rem;color:var(--studio-text);margin-bottom:10px;\">Recent Transformations</h3>\n      <div>\n        ${recentTransforms.map(h=>`\n          <div class=\"recent-row\">\n            <div class=\"recent-thumb\">${room(getPhoto(h.listingId,h.photoId)?.type||'living', 'after', {style:h.options.style||'Modern', time:h.options.style})}</div>\n            <div class=\"recent-body\"><div class=\"r-title\">${TRANSFORMS[h.type].label}</div><div class=\"r-sub\">${h.listingAddr}</div></div>\n            <span class=\"pill pill-${h.status}\">${h.status}</span>\n          </div>\n        `).join('')}\n      </div>\n    </div>\n  </div>`;\n}\n\n/* ---------- Listings gallery ---------- */\nfunction renderListingsGallery(){\n  return `\n  <div class=\"page-head\"><div><h1>Listings</h1><p>Select a listing to open its photo library.</p></div></div>\n  <div class=\"grid-3\">\n    ${S.listings.map(l=>`\n      <div class=\"card listing-card\" onclick=\"LL.go('#/app/listing/${l.id}')\">\n        <div class=\"listing-thumb\">${room(l.photos[0].type, l.photos[0].type==='exterior'?'twilight':'after', {style:'Transitional', time:'Golden Hour'})}</div>\n        <div class=\"listing-info\">\n          <div class=\"addr\">${l.addr}</div>\n          <div class=\"city\">${l.city}</div>\n          <div class=\"listing-meta\">\n            <span>${ICON.photo}${l.photos.length} Photos</span>\n            <span>${ICON.video}${l.videos} Videos</span>\n          </div>\n        </div>\n      </div>\n    `).join('')}\n  </div>`;\n}\n\n/* ---------- Listing detail (photo library) ---------- */\nfunction renderListingDetail(listing){\n  return `\n  <div class=\"page-head\">\n    <div><h1>${listing.addr}</h1><p>${listing.city} · ${listing.photos.length} photos · ${listing.videos} videos</p></div>\n  </div>\n  <div class=\"photo-grid\">\n    ${listing.photos.map(p=>{\n      const has = hasApprovedResult(listing.id,p.id);\n      const displayState = p.type==='exterior' ? 'day' : (p.beforeState==='before'?'before':'empty');\n      return `\n      <div class=\"photo-tile\" onclick=\"LL.go('#/app/listing/${listing.id}/photo/${p.id}')\">\n        ${room(p.type, displayState, {style:'Modern'})}\n        ${has?`<div class=\"tile-badge\">AI Version</div>`:''}\n        <div class=\"tile-room\">${p.room}</div>\n      </div>`;\n    }).join('')}\n  </div>`;\n}\n\nfunction hasApprovedResult(listingId, photoId){\n  return Object.values(S.results).some(r=>r.listingId===listingId && r.photoId===photoId && r.status==='approved')\n    || S.history.some(h=>h.listingId===listingId && h.photoId===photoId && h.status==='approved');\n}\nfunction latestApprovedResult(listingId, photoId){\n  const arr = Object.values(S.results).filter(r=>r.listingId===listingId && r.photoId===photoId && r.status==='approved');\n  return arr.sort((a,b)=>b.createdAt-a.createdAt)[0];\n}\n\n/* ---------- Photo viewer ---------- */\nfunction renderPhotoViewer(listing, photo){\n  const result = latestApprovedResult(listing.id, photo.id);\n  const originalState = photo.type==='exterior' ? 'day' : (photo.beforeState==='before'?'before':'empty');\n  const afterState = photo.type==='exterior' ? 'twilight' : 'after';\n  const opts = result ? result.options : {style:'Modern'};\n  const optsAttr = JSON.stringify(opts).replace(/'/g,'&#39;');\n  return `\n  <div class=\"page-head\">\n    <div><h1>${photo.room}</h1><p>${listing.addr} · ${listing.city}</p></div>\n    <a href=\"#/app/listing/${listing.id}/photo/${photo.id}/studio\" class=\"btn btn-primary\">${ICON.studio} Open AI Studio</a>\n  </div>\n  <div class=\"viewer-shell\">\n    <div class=\"viewer-stage\" id=\"viewerStage\" data-type=\"${photo.type}\" data-opts='${optsAttr}' data-before=\"${originalState}\" data-after=\"${afterState}\" data-watermark=\"${result?TRANSFORMS[result.type].watermark:''}\">\n      ${room(photo.type, result ? afterState : originalState, opts)}\n      ${result?`<div class=\"wm-badge\">${TRANSFORMS[result.type].watermark}</div>`:''}\n    </div>\n    <div class=\"viewer-side\">\n      <div>\n        <div class=\"eyebrow\" style=\"color:var(--studio-brass);\">${photo.room}</div>\n        <h3 style=\"color:var(--studio-text);font-size:1.2rem;margin-top:8px;\">${listing.addr}</h3>\n        <p style=\"color:var(--studio-text-soft);font-size:0.87rem;margin-top:6px;\">${result? 'AI version available. The original is preserved and always accessible.' : 'No AI version yet. Open the studio to generate one.'}</p>\n      </div>\n      ${result?`\n      <div class=\"viewer-toggle\" id=\"viewerToggle\">\n        <button class=\"active\" data-v=\"after\">AI Version</button>\n        <button data-v=\"before\">Original</button>\n      </div>`:''}\n      <hr class=\"rule\">\n      <div>\n        <div class=\"opt-label\">All Photos</div>\n        <div class=\"filmstrip\">\n          ${listing.photos.map(p=>`<div class=\"fs-item ${p.id===photo.id?'active':''}\" style=\"cursor:pointer;\" onclick=\"LL.go('#/app/listing/${listing.id}/photo/${p.id}')\">${room(p.type, p.type==='exterior'?'day':(p.beforeState==='before'?'before':'empty'),{style:'Modern'})}</div>`).join('')}\n        </div>\n      </div>\n    </div>\n  </div>`;\n}\n\n/* ---------- AI Studio ---------- */\nlet studioSel = { type:'declutter', style:null, room:null, time:null, demoFail:false };\n\nfunction renderStudio(listing, photo){\n  if(photo.type==='exterior' && studioSel.type!=='twilight') studioSel = {type:'twilight', style:'Golden Hour', room:null, time:'Golden Hour', demoFail:false};\n  if(photo.type!=='exterior' && studioSel.type==='twilight') studioSel = {type:'declutter', style:null, room:null, time:null, demoFail:false};\n  const tf = TRANSFORMS[studioSel.type];\n  const previewOpts = { style: studioSel.style, time: studioSel.time };\n  const previewState = studioSel.type==='twilight' ? 'twilight' : (studioSel.type==='staging' ? 'after' : 'after');\n  const baseState = photo.type==='exterior' ? 'day' : (photo.beforeState==='before'?'before':'empty');\n  return `\n  <div class=\"page-head\"><div><h1>AI Studio</h1><p>${listing.addr} · ${photo.room}</p></div></div>\n  <div class=\"studio-shell\">\n    <div class=\"studio-stage\">\n      ${beforeAfter(photo.type, baseState, previewState, previewOpts, 'Original', 'Preview')}\n    </div>\n    <div class=\"studio-panel\">\n      <div class=\"tf-tabs\">\n        ${photo.type==='exterior' ? `<div class=\"tf-tab active\" style=\"cursor:default;\">Twilight</div>` : `\n          <div class=\"tf-tab ${studioSel.type==='declutter'?'active':''}\" onclick=\"LL.setTF('declutter')\">Declutter</div>\n          <div class=\"tf-tab ${studioSel.type==='staging'?'active':''}\" onclick=\"LL.setTF('staging')\">Virtual Staging</div>\n        `}\n      </div>\n      <div class=\"tf-body\">\n        <p class=\"tf-desc\">${tf.tagline}</p>\n        ${studioSel.type==='staging' ? `\n          <div>\n            <div class=\"opt-label\">Select Style</div>\n            <div class=\"opt-grid\">\n              ${tf.styles.map(s=>`<button class=\"opt-chip ${studioSel.style===s?'selected':''}\" onclick=\"LL.setOpt('style','${s}')\"><span class=\"swatch\" style=\"background:${styleSwatch(s)}\"></span>${s}</button>`).join('')}\n            </div>\n          </div>\n          <div>\n            <div class=\"opt-label\">Room Type</div>\n            <div class=\"opt-grid\">\n              ${tf.rooms.map(r=>`<button class=\"opt-chip ${studioSel.room===r?'selected':''}\" onclick=\"LL.setOpt('room','${r}')\">${r}</button>`).join('')}\n            </div>\n          </div>\n        `:''}\n        ${studioSel.type==='twilight' ? `\n          <div>\n            <div class=\"opt-label\">Select Mood</div>\n            <div class=\"opt-grid\">\n              ${tf.styles.map(s=>`<button class=\"opt-chip ${studioSel.time===s?'selected':''}\" onclick=\"LL.setOpt('time','${s}')\"><span class=\"swatch\" style=\"background:${timeSwatch(s)}\"></span>${s}</button>`).join('')}\n            </div>\n          </div>\n        `:''}\n        ${studioSel.type==='declutter' ? `\n          <div class=\"card\" style=\"padding:16px 18px;background:var(--studio-surface-2);border-style:dashed;\">\n            <div style=\"font-size:0.82rem;color:var(--studio-text-soft);line-height:1.55;\">Listing Lab removes movable clutter only. Architecture, fixtures and perspective are always preserved — there's nothing to configure.</div>\n          </div>\n        `:''}\n      </div>\n      <div class=\"tf-footer\">\n        <label class=\"demo-toggle\"><input type=\"checkbox\" ${studioSel.demoFail?'checked':''} onchange=\"LL.toggleDemoFail(this.checked)\"> Prototype only: simulate a compliance rejection</label>\n        <div class=\"cost-row\"><span>Cost</span><b>${tf.cost} AI Credit${tf.cost>1?'s':''}</b></div>\n        <button class=\"btn btn-primary btn-block\" ${!canGenerate()?'disabled':''} onclick=\"LL.generate('${listing.id}','${photo.id}')\">Generate</button>\n        ${!canGenerate() && needsOption() ? `<div style=\"font-size:0.78rem;color:var(--studio-terracotta);text-align:center;\">Select the required options above to continue.</div>`:''}\n        ${S.credits < tf.cost ? `<div style=\"font-size:0.78rem;color:var(--studio-terracotta);text-align:center;\">Not enough credits. <a href=\"#/app/credits\" style=\"color:inherit;text-decoration:underline;\">Buy more</a></div>`:''}\n      </div>\n    </div>\n  </div>`;\n}\nfunction styleSwatch(s){ return {Modern:'#33383F',Transitional:'#5B4636',Contemporary:'#AD463C',Coastal:'#3E6E78',Luxury:'#B98A46'}[s]||'#999'; }\nfunction timeSwatch(s){ return {'Golden Hour':'#EE8F63','Dusk':'#4C5B85','Blue Hour':'#212D54'}[s]||'#999'; }\nfunction needsOption(){\n  if(studioSel.type==='staging') return !(studioSel.style && studioSel.room);\n  if(studioSel.type==='twilight') return !studioSel.time;\n  return false;\n}\nfunction canGenerate(){\n  const tf = TRANSFORMS[studioSel.type];\n  if(S.credits < tf.cost) return false;\n  if(needsOption()) return false;\n  return true;\n}\n\nfunction bindStudioInteractions(seg){ /* studio uses inline handlers via LL.* — nothing else to bind */ }\n\n/* ---------- Generation experience ---------- */\nconst GEN_STEPS = ['Preparing photograph…','Applying transformation…','Checking image…','Verifying compliance…','Applying disclosure…','Finalizing image…'];\n\nfunction runGeneration(listingId, photoId){\n  const listing = getListing(listingId), photo = getPhoto(listingId, photoId);\n  const tf = TRANSFORMS[studioSel.type];\n  if(S.credits < tf.cost){ toast('Not enough credits.'); return; }\n  const willFail = studioSel.demoFail;\n  const opts = studioSel.type==='staging' ? {style:studioSel.style, room:studioSel.room} : studioSel.type==='twilight' ? {style:studioSel.time} : {};\n\n  S.credits -= tf.cost; saveState();\n  const overlay = document.createElement('div');\n  overlay.className='overlay';\n  overlay.innerHTML = `\n    <div class=\"overlay-card\">\n      <div class=\"eyebrow\" style=\"color:var(--studio-brass);\">${tf.label}</div>\n      <h3 style=\"color:var(--studio-text);margin-top:10px;font-size:1.3rem;\">Generating your image</h3>\n      <p style=\"color:var(--studio-text-soft);font-size:0.87rem;margin-top:8px;\">Your original photograph is never modified — this creates a new AI derivative.</p>\n      <div class=\"gen-steps\" id=\"genSteps\">\n        ${GEN_STEPS.map((s,i)=>`<div class=\"gen-step\" data-i=\"${i}\"><div class=\"gs-icon\"></div><span>${s}</span></div>`).join('')}\n      </div>\n    </div>`;\n  document.body.appendChild(overlay);\n  const stepEls = overlay.querySelectorAll('.gen-step');\n  const failAtStep = 3; // \"Verifying compliance\"\n  let i=0;\n  function tick(){\n    if(i>0){ stepEls[i-1].classList.remove('active'); stepEls[i-1].classList.add('done'); stepEls[i-1].querySelector('.gs-icon').innerHTML = ICON.check; }\n    if(willFail && i===failAtStep){\n      stepEls[i].classList.add('failed');\n      stepEls[i].querySelector('.gs-icon').innerHTML = ICON.x;\n      stepEls[i].querySelector('.gs-icon').style.color='#0A1017';\n      setTimeout(()=>finishGeneration(overlay, listing, photo, tf, opts, false), 650);\n      return;\n    }\n    if(i>=stepEls.length){ setTimeout(()=>finishGeneration(overlay, listing, photo, tf, opts, true), 350); return; }\n    stepEls[i].classList.add('active');\n    stepEls[i].querySelector('.gs-icon').innerHTML = '<div class=\"spin\"></div>';\n    i++;\n    setTimeout(tick, 620);\n  }\n  tick();\n}\n\nfunction finishGeneration(overlay, listing, photo, tf, opts, passed){\n  const id = uid('res');\n  const histId = uid('h');\n  const date = 'Just now';\n  if(passed){\n    S.results[id] = { id, listingId:listing.id, photoId:photo.id, type:tf.key, options:opts, status:'approved', createdAt:Date.now()+ (nextId) };\n    S.history.unshift({ id:histId, listingId:listing.id, listingAddr:listing.addr, photoId:photo.id, type:tf.key, options:opts, date, status:'approved', cost:tf.cost });\n    saveState();\n    overlay.remove();\n    go('#/app/listing/'+listing.id+'/photo/'+photo.id+'/result/'+id);\n  }else{\n    S.credits += tf.cost; // restore\n    S.history.unshift({ id:histId, listingId:listing.id, listingAddr:listing.addr, photoId:photo.id, type:tf.key, options:opts, date, status:'rejected', cost:0 });\n    saveState();\n    overlay.querySelector('.overlay-card').innerHTML = `\n      <div class=\"result-fail\">\n        <div class=\"fail-icon\">${ICON.warn}</div>\n        <h3 style=\"color:var(--studio-text);font-size:1.25rem;\">Transformation could not be approved.</h3>\n        <p style=\"color:var(--studio-text-soft);font-size:0.9rem;margin-top:14px;line-height:1.6;\">Your original photograph has not been changed.<br>Your AI credit has been restored.</p>\n        <button class=\"btn btn-primary btn-block\" style=\"margin-top:26px;\" onclick=\"this.closest('.overlay').remove()\">Try Again</button>\n      </div>`;\n    render();\n  }\n}\n\n/* ---------- Result screen ---------- */\nfunction renderResult(listing, photo, result){\n  const tf = TRANSFORMS[result.type];\n  const afterState = photo.type==='exterior' ? 'twilight' : 'after';\n  const originalState = photo.type==='exterior' ? 'day' : (photo.beforeState==='before'?'before':'empty');\n  return `\n  <div class=\"page-head\"><div><h1>Result</h1><p>${listing.addr} · ${photo.room} · ${tf.label}</p></div><span class=\"pill pill-approved\">${ICON.checkCircle} Approved</span></div>\n  <div class=\"result-shell\">\n    <div>\n      <div class=\"viewer-toggle\" id=\"resultToggle\" style=\"margin-bottom:14px;\">\n        <button class=\"active\" data-v=\"after\">AI Version</button>\n        <button data-v=\"before\">Original</button>\n      </div>\n      <div class=\"result-stage\" id=\"resultStage\" data-type=\"${photo.type}\" data-opts='${JSON.stringify(result.options).replace(/'/g,'&#39;')}' data-before=\"${originalState}\" data-after=\"${afterState}\" data-watermark=\"${tf.watermark}\">\n        ${room(photo.type, afterState, result.options)}\n        <div class=\"wm-badge\">${tf.watermark}</div>\n      </div>\n    </div>\n    <div>\n      <div class=\"card\" style=\"padding:24px;\">\n        <h3 style=\"color:var(--studio-text);font-size:1.1rem;\">Compliance passed</h3>\n        <p style=\"color:var(--studio-text-soft);font-size:0.86rem;margin-top:8px;line-height:1.55;\">This result stayed within the approved ${tf.label.toLowerCase()} transformation and was watermarked automatically before delivery.</p>\n        <hr class=\"rule\" style=\"margin:20px 0;\">\n        <div class=\"result-actions\">\n          <button class=\"btn btn-primary btn-block\" onclick=\"LL.toast('Download started.')\">${ICON.download} Download</button>\n          <button class=\"btn btn-ghost btn-block\" onclick=\"LL.saveToListing('${listing.id}')\">${ICON.save} Save to Listing</button>\n          <button class=\"btn btn-ghost btn-block\" onclick=\"LL.toast('Share link copied.')\">${ICON.share} Share</button>\n          <a class=\"btn btn-quiet btn-block\" href=\"#/app/listing/${listing.id}/photo/${photo.id}/studio\">${ICON.again} Create Another</a>\n        </div>\n      </div>\n    </div>\n  </div>`;\n}\n\n/* ---------- Credits ---------- */\nfunction renderCredits(){\n  return `\n  <div class=\"page-head\"><div><h1>Credits</h1><p>Buy credits and see exactly what each transformation costs.</p></div></div>\n  <div class=\"stat-row\" style=\"grid-template-columns:1fr;margin-bottom:34px;\">\n    <div class=\"card stat-card\" style=\"display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:20px;\">\n      <div><div class=\"stat-label\">Current Balance</div><div class=\"stat-value\">${S.credits} Credits</div></div>\n      <div style=\"display:flex;gap:22px;font-size:0.85rem;color:var(--studio-text-soft);\">\n        <span>Virtual Stage &nbsp;<b style=\"color:var(--studio-text)\">2 credits</b></span>\n        <span>Declutter &nbsp;<b style=\"color:var(--studio-text)\">1 credit</b></span>\n        <span>Twilight &nbsp;<b style=\"color:var(--studio-text)\">1 credit</b></span>\n      </div>\n    </div>\n  </div>\n  <div class=\"grid-3\">\n    ${PACKS.map((p,i)=>`\n      <div class=\"card pack-card ${p.best?'best':''}\">\n        ${p.best?'<div class=\"best-tag\">Best Value</div>':''}\n        <h4 style=\"color:var(--studio-text-soft);font-size:1rem;\">${p.credits} Credits</h4>\n        <div style=\"font-family:var(--display);font-size:2.2rem;color:var(--studio-text);margin:12px 0 4px;\">$${p.price.toFixed(2)}</div>\n        <div style=\"font-size:0.8rem;color:var(--studio-text-faint);margin-bottom:22px;\">$${(p.price/p.credits).toFixed(2)} per credit</div>\n        <button class=\"btn btn-primary btn-block\" onclick=\"LL.buyCredits(${p.credits})\">Buy Credits</button>\n      </div>\n    `).join('')}\n  </div>`;\n}\n\n/* ---------- History ---------- */\nlet historyFilter='all';\nfunction renderHistory(){\n  const rows = S.history.filter(h=> historyFilter==='all' || h.status===historyFilter);\n  return `\n  <div class=\"page-head\"><div><h1>Transformation History</h1><p>Every generation, its options, and its compliance result.</p></div></div>\n  <div class=\"filter-row\">\n    ${['all','approved','rejected'].map(f=>`<button class=\"filter-chip ${historyFilter===f?'active':''}\" onclick=\"LL.setHistFilter('${f}')\">${f[0].toUpperCase()+f.slice(1)}</button>`).join('')}\n  </div>\n  <div class=\"card\" style=\"padding:8px 20px;overflow-x:auto;\">\n    <table class=\"hist-table\">\n      <thead><tr><th>Photo</th><th>Type</th><th>Options</th><th>Listing</th><th>Date</th><th>Status</th><th>Cost</th></tr></thead>\n      <tbody>\n        ${rows.length===0? `<tr><td colspan=\"7\"><div class=\"empty-state\">No transformations yet.</div></td></tr>` : rows.map(h=>{\n          const photo = getPhoto(h.listingId,h.photoId);\n          const optStr = Object.values(h.options||{}).filter(Boolean).join(' · ') || '—';\n          return `\n          <tr>\n            <td><div class=\"hist-thumb\">${room(photo?photo.type:'living', h.status==='approved'?'after':'before', h.options)}</div></td>\n            <td class=\"h-type\">${TRANSFORMS[h.type].label}</td>\n            <td>${optStr}</td>\n            <td>${h.listingAddr}</td>\n            <td>${h.date}</td>\n            <td><span class=\"pill pill-${h.status}\">${h.status}</span></td>\n            <td>${h.cost} cr</td>\n          </tr>`;\n        }).join('')}\n      </tbody>\n    </table>\n  </div>`;\n}\n\n/* ============================================================\n   ADMIN DASHBOARD — Horizon Home Media internal (mock data)\n   ============================================================ */\nconst ADMIN = __ADMIN_DATA__;\nconst esc = s => String(s == null ? '' : s).replace(/[&<>\"']/g, c => '&#' + c.charCodeAt(0) + ';');\n\nfunction roundedTopRect(x,y,w,h,r){\n  if(h<=r) r=Math.max(1,h/2);\n  return `M${x} ${y+r} a${r} ${r} 0 0 1 ${r} -${r} h${w-2*r} a${r} ${r} 0 0 1 ${r} ${r} v${h-r} h${-w} z`;\n}\n\nfunction stackedColumnsSVG(){\n  const W=720, H=252, x0=40, x1=712, y0=14, y1=222;\n  const nWeeks = ADMIN.weeks.length;\n  const slot = (x1-x0)/nWeeks, barW = Math.min(24, slot-14);\n  const totals = ADMIN.weeks.map((_,i)=>ADMIN.series.reduce((a,s)=>a+s.values[i],0));\n  const yMax = 50, scale = (y1-y0)/yMax;\n  let out = '';\n  // gridlines + ticks (hairline, recessive; clean numbers)\n  for(let v=0; v<=yMax; v+=10){\n    const y = y1 - v*scale;\n    out += `<line x1=\"${x0}\" y1=\"${y.toFixed(1)}\" x2=\"${x1}\" y2=\"${y.toFixed(1)}\" stroke=\"var(--viz-grid)\" stroke-width=\"1\"/>`;\n    out += `<text x=\"${x0-8}\" y=\"${(y+3.5).toFixed(1)}\" text-anchor=\"end\" font-size=\"10.5\" fill=\"var(--studio-text-faint)\" style=\"font-variant-numeric:tabular-nums\">${v}</text>`;\n  }\n  // columns: segments bottom-up with 2px surface gaps; only topmost gets the rounded data-end\n  for(let i=0;i<nWeeks;i++){\n    const cx = x0 + slot*i + (slot-barW)/2;\n    let cursor = y1;\n    ADMIN.series.forEach((s,si)=>{\n      const h = s.values[i]*scale - (si>0 ? 2 : 0);\n      const top = cursor - s.values[i]*scale;\n      const isTop = si===ADMIN.series.length-1;\n      if(isTop){ out += `<path d=\"${roundedTopRect(cx, top, barW, cursor-top, 4)}\" fill=\"${s.color}\"/>`; }\n      else{ out += `<rect x=\"${cx}\" y=\"${top+(si>0?2:0)}\" width=\"${barW}\" height=\"${Math.max(1,h)}\" fill=\"${s.color}\"/>`; }\n      cursor = top;\n    });\n    // selective direct label: final week's total only\n    if(i===nWeeks-1){ out += `<text x=\"${cx+barW/2}\" y=\"${(cursor-7).toFixed(1)}\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"700\" fill=\"var(--studio-text)\">${totals[i]}</text>`; }\n    // x labels every other week\n    if(i%2===0){ out += `<text x=\"${cx+barW/2}\" y=\"${y1+16}\" text-anchor=\"middle\" font-size=\"10\" fill=\"var(--studio-text-faint)\">${ADMIN.weeks[i]}</text>`; }\n    // hover hit target (full slot height)\n    out += `<rect class=\"col-hit\" data-week=\"${i}\" x=\"${x0+slot*i}\" y=\"${y0}\" width=\"${slot}\" height=\"${y1-y0}\" fill=\"transparent\"/>`;\n  }\n  out += `<line x1=\"${x0}\" y1=\"${y1}\" x2=\"${x1}\" y2=\"${y1}\" stroke=\"var(--viz-axis)\" stroke-width=\"1\"/>`;\n  return `<svg class=\"chart-svg\" viewBox=\"0 0 ${W} ${H}\" role=\"img\" aria-label=\"Weekly transformations by type\">${out}</svg>`;\n}\n\nfunction sparklineSVG(points, w, h){\n  const min=Math.min(...points), max=Math.max(...points);\n  const px = i => (i/(points.length-1))*(w-8)+4;\n  const py = v => h-5-((v-min)/(max-min))*(h-12);\n  const d = points.map((v,i)=>`${i?'L':'M'}${px(i).toFixed(1)} ${py(v).toFixed(1)}`).join('');\n  const lx=px(points.length-1), ly=py(points[points.length-1]);\n  return `<svg class=\"spark\" viewBox=\"0 0 ${w} ${h}\" preserveAspectRatio=\"none\" aria-hidden=\"true\">\n    <path d=\"${d}\" fill=\"none\" stroke=\"#3A4656\" stroke-width=\"2\" stroke-linejoin=\"round\" stroke-linecap=\"round\"/>\n    <circle cx=\"${lx}\" cy=\"${ly}\" r=\"4\" fill=\"var(--s1)\" stroke=\"var(--studio-surface)\" stroke-width=\"2\"/>\n  </svg>`;\n}\n\nfunction renderAdminShell(){\n  const k = ADMIN.kpis;\n  const seriesTotals = ADMIN.series.map(s=>({ ...s, total: s.values.reduce((a,b)=>a+b,0) }));\n  const grandTotal = seriesTotals.reduce((a,s)=>a+s.total,0);\n  const maxTotal = Math.max(...seriesTotals.map(s=>s.total));\n  return `\n  <div class=\"studio viz\">\n    <div class=\"studio-topbar\">\n      <div class=\"wrap studio-topbar-row\">\n        <a href=\"#/\" class=\"mark\">${ICON.logoMark}<span>Listing&nbsp;<span class=\"lab\">Lab</span></span></a>\n        <span class=\"admin-badge\">${ICON.account} Listing Lab · Admin</span>\n        <a href=\"/\" target=\"_blank\" rel=\"noopener\" class=\"btn btn-ghost btn-sm\">Open Listing Lab →</a>\n      </div>\n    </div>\n    <div class=\"wrap\" style=\"padding-bottom:80px;\">\n      <div class=\"page-head\" style=\"padding-top:34px;\">\n        <div><h1>Listing Lab dashboard</h1><p>${ADMIN.period} · internal only — customers never see this view.</p></div>\n      </div>\n\n      <div class=\"kpi-row\">\n        <div class=\"card kpi\">\n          <div class=\"k-label\">Revenue</div>\n          <div class=\"k-value\">$${k.revenue.toLocaleString('en-US',{minimumFractionDigits:2})}</div>\n          <div class=\"k-delta up\">${k.revenueDelta}</div>\n          ${sparklineSVG(ADMIN.revenueSpark, 180, 30)}\n        </div>\n        <div class=\"card kpi\"><div class=\"k-label\">Credits sold</div><div class=\"k-value\">${k.creditsSold}</div><div class=\"k-delta muted\">across all packs</div></div>\n        <div class=\"card kpi\"><div class=\"k-label\">Credits consumed</div><div class=\"k-value\">${k.creditsUsed}</div><div class=\"k-delta muted\">${grandTotal} transformations</div></div>\n        <div class=\"card kpi\"><div class=\"k-label\">AI processing cost</div><div class=\"k-value\">$${k.aiCost.toFixed(2)}</div><div class=\"k-delta muted\">incl. retries &amp; rejected runs</div></div>\n        <div class=\"card kpi\"><div class=\"k-label\">Compliance pass rate</div><div class=\"k-value\">${k.passRate}%</div><div class=\"k-delta muted\">${k.rejected} rejected · credits restored</div></div>\n      </div>\n\n      ${(()=>{ const svc = getService(); return `\n      <div class=\"card chart-card\" style=\"margin-bottom:26px;\">\n        <h3>Service controls</h3>\n        <div class=\"c-sub\">The owner kill switch. In production each toggle flips a backend flag that every customer session honors within seconds — pause sales first, generation only if you must.</div>\n        <div style=\"margin-top:6px;\">\n          <div class=\"svc-row\">\n            <span class=\"svc-name\">Credit sales</span>\n            <span class=\"svc-status ${svc.salesPaused?'off':'on'}\">${svc.salesPaused?'Paused':'Active'}</span>\n            <span class=\"svc-desc\">${svc.salesPaused\n              ? 'The store is closed: Buy buttons are disabled and customers see \\u201cCredit sales are temporarily paused — existing credits work normally.\\u201d Tools keep running.'\n              : 'Customers can buy credit packs normally. Pausing this is the first lever — it caps your obligation without breaking anything for paying customers.'}</span>\n            <label class=\"switch\"><input type=\"checkbox\" ${svc.salesPaused?'checked':''} onchange=\"LL.svcToggle('salesPaused',this.checked)\"><span class=\"track\"></span><span class=\"knob\"></span></label>\n          </div>\n          <div class=\"svc-row\">\n            <span class=\"svc-name\">AI generation</span>\n            <span class=\"svc-status ${svc.genPaused?'off':'on'}\">${svc.genPaused?'Paused':'Active'}</span>\n            <span class=\"svc-desc\">${svc.genPaused\n              ? 'Full stop: Generate is disabled everywhere and customers see \\u201cAI generation is temporarily paused. Your credits are safe and never expire.\\u201d Zero API spend while paused.'\n              : 'Transformations run normally. Pausing this halts all Google API spend instantly — the emergency brake.'}</span>\n            <label class=\"switch\"><input type=\"checkbox\" ${svc.genPaused?'checked':''} onchange=\"LL.svcToggle('genPaused',this.checked)\"><span class=\"track\"></span><span class=\"knob\"></span></label>\n          </div>\n        </div>\n      </div>`; })()}\n      <div class=\"admin-grid\">\n        <div class=\"card chart-card\">\n          <h3>Transformations per week</h3>\n          <div class=\"c-sub\">Approved generations by type</div>\n          <div class=\"legend-row\">\n            ${ADMIN.series.map(s=>`<span class=\"legend-item\"><span class=\"dot\" style=\"background:${s.color}\"></span>${s.label}</span>`).join('')}\n          </div>\n          ${stackedColumnsSVG()}\n        </div>\n        <div style=\"display:flex;flex-direction:column;gap:22px;\">\n          <div class=\"card chart-card\">\n            <h3>Share by transformation</h3>\n            <div class=\"c-sub\">Most popular: ${seriesTotals.slice().sort((a,b)=>b.total-a.total)[0].label} (${Math.round(seriesTotals.slice().sort((a,b)=>b.total-a.total)[0].total/grandTotal*100)}%)</div>\n            ${seriesTotals.map(s=>`\n              <div class=\"share-row\">\n                <span class=\"s-label\">${s.label}</span>\n                <div class=\"share-track\"><div class=\"fill\" style=\"width:${(s.total/maxTotal*100).toFixed(1)}%;background:${s.color}\"></div></div>\n                <span class=\"s-val\">${s.total}</span>\n              </div>`).join('')}\n          </div>\n          <div class=\"card chart-card\">\n            <h3>Compliance</h3>\n            <div class=\"c-sub\">${k.passRate}% of generations approved on delivery check</div>\n            <div class=\"meter\" role=\"img\" aria-label=\"Pass rate ${k.passRate}%\"><div class=\"fill\" style=\"width:${k.passRate}%\"></div></div>\n            <div class=\"admin-table-note\">Every rejected generation restored its credit automatically. No unapproved image was delivered.</div>\n          </div>\n        </div>\n      </div>\n\n      <div class=\"admin-grid admin-grid-2\">\n        <div class=\"card chart-card\">\n          <h3>Recent compliance rejections</h3>\n          <div style=\"overflow-x:auto;margin-top:8px;\">\n            <table class=\"hist-table\">\n              <thead><tr><th>Date</th><th>Listing</th><th>Type</th><th>Reason</th><th>Action</th></tr></thead>\n              <tbody>${ADMIN.failures.map(f=>`\n                <tr><td>${f.date}</td><td>${esc(f.listing)}</td><td class=\"h-type\">${f.type}</td><td>${esc(f.reason)}</td><td><span class=\"pill ${f.resolved?'pill-pass':'pill-fail'}\">${f.resolved?ICON.checkCircle:ICON.warn} ${f.action}</span></td></tr>`).join('')}\n              </tbody>\n            </table>\n          </div>\n        </div>\n        <div class=\"card chart-card\">\n          <h3>Customer usage</h3>\n          <div style=\"overflow-x:auto;margin-top:8px;\">\n            <table class=\"hist-table\">\n              <thead><tr><th>Agent</th><th>Brokerage</th><th>Transformations</th><th>Credits</th><th>Last active</th></tr></thead>\n              <tbody>${ADMIN.customers.map(c=>`\n                <tr><td class=\"h-type\">${esc(c.name)}</td><td>${esc(c.org)}</td><td style=\"font-variant-numeric:tabular-nums\">${c.tx}</td><td style=\"font-variant-numeric:tabular-nums\">${c.credits}</td><td>${c.last}</td></tr>`).join('')}\n              </tbody>\n            </table>\n          </div>\n        </div>\n      </div>\n\n      <div class=\"card chart-card\">\n        <h3>Transformation audit log</h3>\n        <div class=\"c-sub\">Internal record of every generation — inputs, attempts, compliance result, credit movement.</div>\n        <div style=\"overflow-x:auto;margin-top:8px;\">\n          <table class=\"hist-table\">\n            <thead><tr><th>Timestamp</th><th>Listing</th><th>Photo</th><th>Type</th><th>Options</th><th>Attempts</th><th>Compliance</th><th>Credits</th></tr></thead>\n            <tbody>${ADMIN.audit.map(a=>`\n              <tr>\n                <td style=\"white-space:nowrap;\">${a.ts}</td><td>${esc(a.listing)}</td><td>${esc(a.photo)}</td>\n                <td class=\"h-type\">${a.type}</td><td>${a.opts}</td>\n                <td style=\"font-variant-numeric:tabular-nums\">${a.attempts}</td>\n                <td>${a.result==='pass' ? `<span class=\"pill pill-pass\">${ICON.checkCircle} Approved</span>` : `<span class=\"pill pill-fail\">${ICON.warn} Rejected</span>`}</td>\n                <td style=\"font-variant-numeric:tabular-nums\">${a.cost} cr</td>\n              </tr>`).join('')}\n            </tbody>\n          </table>\n        </div>\n        <div class=\"admin-table-note\">Rejected runs consume 0 credits — the charge is reversed before the customer sees a result.</div>\n      </div>\n    </div>\n  </div>\n  <div id=\"chart-tip\"></div>`;\n}\n\nfunction afterAdminRender(){\n  const tip = document.getElementById('chart-tip');\n  document.querySelectorAll('.col-hit').forEach(hit=>{\n    hit.addEventListener('mousemove', e=>{\n      const i = +hit.dataset.week;\n      const total = ADMIN.series.reduce((a,s)=>a+s.values[i],0);\n      tip.innerHTML = `<div class=\"t-title\">Week of ${ADMIN.weeks[i]}</div>`\n        + ADMIN.series.map(s=>`<div class=\"t-row\"><span><span class=\"dot\" style=\"background:${s.hex}\"></span>${s.label}</span><span class=\"t-val\">${s.values[i]}</span></div>`).join('')\n        + `<div class=\"t-row\" style=\"border-top:1px solid var(--studio-line);margin-top:5px;padding-top:5px;\"><span>Total</span><span class=\"t-val\">${total}</span></div>`;\n      tip.style.display='block';\n      const tw = tip.offsetWidth;\n      tip.style.left = Math.min(e.clientX+14, window.innerWidth-tw-10)+'px';\n      tip.style.top = (e.clientY+14)+'px';\n    });\n    hit.addEventListener('mouseleave', ()=>{ tip.style.display='none'; });\n  });\n}\n\n/* ---------- Account ---------- */\nfunction renderAccount(){\n  return `\n  <div class=\"page-head\"><div><h1>Account</h1><p>Prototype placeholder — production connects to Aryeo for authentication.</p></div></div>\n  <div class=\"card\" style=\"padding:30px;max-width:480px;\">\n    <div style=\"display:flex;align-items:center;gap:16px;\">\n      <div style=\"width:56px;height:56px;border-radius:50%;background:var(--studio-surface-2);display:flex;align-items:center;justify-content:center;color:var(--studio-brass);\">${ICON.account}</div>\n      <div><div style=\"color:var(--studio-text);font-weight:600;\">Horizon Home Media</div><div style=\"color:var(--studio-text-soft);font-size:0.85rem;\">Photographer account · Connecticut</div></div>\n    </div>\n    <hr class=\"rule\" style=\"margin:22px 0;\">\n    <div style=\"font-size:0.85rem;color:var(--studio-text-soft);line-height:1.7;\">Listings sync from Aryeo once connected.<br>Credits and transformation history are tied to this account.</div>\n    <hr class=\"rule\" style=\"margin:22px 0;\">\n    <div style=\"display:flex;align-items:center;justify-content:space-between;gap:14px;flex-wrap:wrap;\">\n      <div style=\"font-size:0.8rem;color:var(--studio-text-faint);max-width:26ch;\">Listing Lab dashboard — internal business view, owners only.</div>\n      <a href=\"#/admin\" class=\"btn btn-ghost btn-sm\">Open Dashboard</a>\n    </div>\n  </div>`;\n}\n\n/* ============================================================\n   GLOBAL ACTIONS (bound to window for inline handlers)\n   ============================================================ */\nwindow.LL = {\n  go,\n  toast,\n  setTF(t){ studioSel = {type:t, style:null, room:null, time:null, demoFail:studioSel.demoFail}; render(); },\n  setOpt(k,v){ studioSel[k]=v; render(); },\n  toggleDemoFail(v){ studioSel.demoFail=v; },\n  generate(listingId, photoId){ runGeneration(listingId, photoId); },\n  buyCredits(n){ S.credits += n; saveState(); render(); toast('Added '+n+' credits.'); },\n  setHistFilter(f){ historyFilter=f; render(); },\n  saveToListing(listingId){ const l=getListing(listingId); toast(l?('Saved to '+l.addr+'.'):'Saved to listing.'); },\n};\n\n/* Owner kill switch state (prototype: stored locally; production: a\n   backend flag every customer session checks before selling or generating). */\nconst SVC_KEY = 'listinglab_service_v1';\nlet __SVC = __SVC_DATA__;\nfunction getService(){ return __SVC; }\nwindow.LL.svcToggle = function(k, v){\n  const prev = { ...__SVC };\n  __SVC[k] = v; render();\n  fetch('/internal/board/flags?s=' + encodeURIComponent(__BOARD_SECRET__), {\n    method: 'POST',\n    headers: { 'content-type': 'application/json' },\n    body: JSON.stringify({ key: k, value: v }),\n  }).then(r => {\n    if (!r.ok) throw new Error('HTTP ' + r.status);\n    toast(v ? 'Paused — customers see the paused notice immediately.' : 'Resumed — back to normal for all customers.');\n  }).catch(() => { __SVC = prev; render(); toast('Could not save that — nothing changed.'); });\n};\n\n/* toggle bindings for before/original views (delegated) — regenerates the\n   illustration from its data attributes rather than toggling CSS classes,\n   since exterior twilight lighting is baked in at render time. */\ndocument.addEventListener('click', function(e){\n  const btn = e.target.closest('#viewerToggle button, #resultToggle button');\n  if(!btn) return;\n  const wrap = btn.closest('.viewer-toggle');\n  wrap.querySelectorAll('button').forEach(b=>b.classList.remove('active'));\n  btn.classList.add('active');\n  const stage = wrap.id==='resultToggle' ? document.getElementById('resultStage') : document.getElementById('viewerStage');\n  if(!stage) return;\n  const showAfter = btn.dataset.v==='after';\n  const type = stage.dataset.type;\n  let opts = {};\n  try{ opts = JSON.parse(stage.dataset.opts||'{}'); }catch(err){}\n  const state = showAfter ? stage.dataset.after : stage.dataset.before;\n  const wm = stage.dataset.watermark;\n  stage.innerHTML = room(type, state, opts) + (showAfter && wm ? `<div class=\"wm-badge\">${wm}</div>` : '');\n});\n\nrender();\n})();\n</script>\n\n\n</body></html>";
